function AiCell({ row }: { row: BatchRowFixture }) {
  switch (row.ai) {
    case "drafted":
      return (
        <span className="bc-status bc-status--ok">
          <CheckCircleIcon className="bc-icon" />
          Brief, market research and SEO done
        </span>
