                <td>
                  <ProposalCell row={row} />
                </td>
                <td>
                  {gone || row.ai === "queued" || row.ai === "drafting" ? (
                    <span className="bc-muted">—</span>
                  ) : row.reviewed ? (
                    <button type="button" className="bc-quiet bc-quiet--on" title="Mark needs review">
