const groups = { add: "Add to Etsy", change: "Change on Etsy", remove: "Remove from Etsy" };
const stagesOf = (row: Change) => (row.group === "remove" ? retractPipeline : pipeline);
const runCount = (row: Change) => stagesOf(row).filter((s) => row.stages[s.key].run).length;

// Where the run has got to: apply is on this listing, inside this stage.
const cursor = { listing: "mountain-sunrise-tee", stage: "etsy_listing" };
const listingAt = changes.findIndex((c) => c.id === cursor.listing);

type State = "done" | "running" | "waiting" | "skip";

// Per listing, per stage — because `apply_listings` walks one listing's whole
// pipeline before the next one starts. Nothing here is run-wide.
function stateOf(row: Change, stageKey: string): State {
  if (!row.stages[stageKey]?.run) return "skip";
  const at = changes.indexOf(row);
  if (at < listingAt) return "done";
  if (at > listingAt) return "waiting";
  const running = stagesOf(row)
    .filter((s) => row.stages[s.key].run)
    .map((s) => s.key);
  const i = running.indexOf(stageKey);
  const c = running.indexOf(cursor.stage);
  return i < c ? "done" : i === c ? "running" : "waiting";
}

const rowState = (row: Change): State => {
  const at = changes.indexOf(row);
  return at < listingAt ? "done" : at === listingAt ? "running" : "waiting";
};
const rowLabel = { done: "Applied", running: "Applying now", waiting: "Waiting", skip: "Skipped" };

// The run's read of the same stages: which listings each one covers.
const runStages = [...pipeline, ...retractPipeline].map((stage) => ({
  ...stage,
  items: changes
    .filter((c) => c.stages[stage.key]?.run)
    .map((c) => ({ id: c.id, title: c.title, why: c.stages[stage.key].why })),
}));

function Mark({ state }: { state: State }) {
  const done = state === "done";
  return (
    <span
      aria-hidden="true"
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        width: 13,
        height: 13,
        flex: "0 0 13px",
        border: "1px solid #111",
        background: done ? "#111" : "#fff",
        color: "#fff",
        fontSize: 9,
        lineHeight: 1,
      }}
    >
      {done ? (
        "✓"
      ) : state === "running" ? (
        <span style={{ width: 5, height: 5, background: "#111" }} />
      ) : null}
    </span>
  );
}

function StageDot({ state }: { state: State }) {
  return (
    <span
      aria-hidden="true"
      style={{
        display: "inline-block",
        width: 10,
        height: 10,
        flex: "0 0 10px",
        border: `1px solid ${state === "skip" ? "#777" : "#111"}`,
        background: state === "done" ? "#111" : "#fff",
        borderRadius: state === "running" ? "50%" : 0,
      }}
    />
  );
}

