        <Mark state={state} />
        <span>
          <strong>{row.title}</strong> <span style={{ color: "#555" }}>— {row.copy}</span>
        </span>
      </span>
      <span style={{ color: state === "waiting" ? "#555" : "#111", whiteSpace: "nowrap" as const }}>
        {rowLabel[state]} · {done} of {runCount(row)} stages →
      </span>
    </button>
  );
}

// The individual listing page's step strip — src/pages/deploy/StepStrip.tsx —
// wearing this run's live state instead of the plan's.
function StepStrip({ row }: { row: Change }) {
  const stages = stagesOf(row);
  const why = { done: "Done", running: "Running", waiting: "Not yet", skip: "No changes" };
  return (
    <section>
      <p style={{ margin: "0 0 8px", color: "#555" }}>
        What apply is doing · {runCount(row)} of {stages.length} stage{stages.length > 1 ? "s" : ""}
      </p>
      <div
        className="wf-steps"
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))",
          border: "1px solid #999",
        }}
      >
        {stages.map((s, i) => {
          const plan = row.stages[s.key];
          const state = stateOf(row, s.key);
          return (
            <div
              key={s.key}
              style={{
                padding: 12,
                borderLeft: i === 0 ? "none" : "1px solid #999",
                background: state === "skip" ? "#f1f1f1" : state === "running" ? "#fafafa" : "#fff",
                outline: state === "running" ? "1px solid #111" : "none",
                outlineOffset: -1,
              }}
            >
              <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <StageDot state={state} />
                <strong style={{ fontSize: 13, color: state === "skip" ? "#555" : "#111" }}>
                  {s.label}
                </strong>
              </span>
              <p style={{ margin: "6px 0 0", fontSize: 12.5, color: "#555" }}>
                {why[state]}
                {state === "waiting" || state === "running" ? ` · ${plan.why}` : ""}
              </p>
              {plan.run && plan.actions.length > 0 && (
                <details style={{ marginTop: 6, fontSize: 12 }} open={state === "running"}>
                  <summary style={{ cursor: "pointer" }}>
                    {plan.actions.length} action{plan.actions.length > 1 ? "s" : ""}
                  </summary>
                  <ul style={{ margin: "4px 0 0", paddingLeft: 16, color: "#555" }}>
                    {plan.actions.map((a) => (
                      <li key={a}>{a}</li>
                    ))}
                  </ul>
                </details>
              )}
            </div>
          );
        })}
      </div>
    </section>
  );
}

