                    {infoText("lighting")}
                    <select
                      id={`lighting-${state}`}
                      className="input"
                      value={light}
                      onChange={(e) => setLight(e.target.value)}
                    >
                      <option>Prepared garment lighting</option>
                      <option>Photo-based lighting</option>
                    </select>
                    <Slider
                      label="Light & shadow strength"
                      value={shading}
                      onChange={setShading}
                      low="original design"
                      high="match cloth"
