                    {infoText("shading")}
                    <Slider
                      label="Fabric texture"
                      value={texture}
                      onChange={setTexture}
                      low="smooth"
                      high="textured"
                      info={infoButton("texture")}
                    />
                    {infoText("texture")}
                    <Slider
                      label="Print shine"
                      value={highlights}
                      onChange={setHighlights}
                      low="matte"
                      high="shiny"
                      info={infoButton("highlights")}
