                  .filter(
                    (t) =>
                      (!query || t.label.toLowerCase().includes(query.toLowerCase())) &&
                      (!kindFilter || t.kind === kindFilter) &&
                      (statusFilter === "All" ||
                        (statusFilter === "Ready"
                          ? t.name === selectedName
                            ? ready
