                    {view === "calibrate" ? (
                      <>
                        <span className="mg-main-photo">
                          {isMultiple ? "Main image" : "Main image · Bay"}
                        </span>
                        <label className="app__outline-toggle">
                          <input
                            type="checkbox"
                            checked={outlines}
                            onChange={(e) => setOutlines(e.target.checked)}
                          />
                          show outline
                        </label>
                      </>
                    ) : null}
                  </div>
                  {view === "calibrate" ? (
                    <>
                      <div className="mg-image-toolbar" aria-label="Placement and mask tools">
                        {isMultiple && (
                          <select
                            className="input mg-placement-select"
                            aria-label="Selected placement"
                            value={selected}
                            onChange={(e) => setSelected(Number(e.target.value))}
