                            <option value="0">Placement 1 · Ivory</option>
                            <option value="1">Placement 2 · Yam</option>
                          </select>
                        )}
                        <div className="mg-tool-buttons" role="toolbar" aria-label="Image tools">
                          {(
                            [
                              { value: "placement", label: "Move placement", icon: HandIcon },
                              { value: "exclude", label: "Exclude", icon: PaintBrushIcon },
                              { value: "restore", label: "Restore", icon: EraserIcon },
                            ] as const
                          ).map((t) => (
                            <button
                              key={t.value}
                              className={`btn btn-secondary ${tool === t.value ? "mg-tool--selected" : ""}`}
                              aria-pressed={tool === t.value}
                              onClick={() => {
                                setTool(t.value);
                                if (t.value !== "placement") setShowMask(true);
                              }}
                            >
                              <t.icon weight="bold" />
                              {t.label}
                            </button>
                          ))}
                          <button
                            className="btn btn-ghost mg-undo"
                            aria-label="Undo mask stroke"
                            disabled={!brushHistory.length}
                            onClick={() => {
                              setStrokes(strokes.slice(0, brushHistory.at(-1)));
                              setBrushHistory(brushHistory.slice(0, -1));
                            }}
                          >
                            <ArrowCounterClockwiseIcon weight="bold" />
                            Undo
                          </button>
                        </div>
                        <div className="mg-mask-options">
                          <span className="mg-field-title">
                            <label className="mg-checkbox">
                              <input
                                type="checkbox"
                                checked={mask}
                                onChange={(e) => setMask(e.target.checked)}
                              />
                              Use automatic cloth mask
                            </label>
                            {infoButton("mask")}
                          </span>
                          <label className="mg-checkbox">
                            <input
                              type="checkbox"
                              checked={showMask}
                              onChange={(e) => setShowMask(e.target.checked)}
                            />
                            Show mask
                          </label>
                        </div>
                        {infoText("mask")}
                        <div className="mg-mask-actions">
                          <span className="mg-mask-key">
                            <span />
                            Tinted areas exclude the print
                          </span>
                          <button
                            className="btn btn-ghost mg-reset"
                            onClick={() => {
                              setBoxes(isMultiple ? pairBoxes : [initialBox]);
                              setStrokes([]);
                              setBrushHistory([]);
                              setTool("placement");
                              setMask(true);
                            }}
                          >
                            Reset placement & mask
                          </button>
                        </div>
                        {tool !== "placement" && (
                          <Slider
                            label="Brush size"
                            value={brushSize}
                            onChange={setBrushSize}
                            low="fine"
                            high="broad"
                          />
                        )}
                      </div>
                      <div
                        className={`mg-stage ${tool !== "placement" ? "mg-stage--mask" : ""}`}
                        onPointerDown={(e) => {
                          if (tool === "placement") return;
                          e.currentTarget.setPointerCapture(e.pointerId);
                          setBrushHistory([...brushHistory, strokes.length]);
                          const r = e.currentTarget.getBoundingClientRect();
                          setStrokes([
                            ...strokes,
                            {
                              x: ((e.clientX - r.left) / r.width) * 100,
                              y: ((e.clientY - r.top) / r.height) * 100,
                              mode: tool,
                              size: brushSize,
                            },
                          ]);
                        }}
                        onPointerMove={(e) => {
                          if (tool === "placement" || !e.buttons) return;
                          const r = e.currentTarget.getBoundingClientRect();
                          setStrokes((old) => [
                            ...old,
                            {
                              x: ((e.clientX - r.left) / r.width) * 100,
                              y: ((e.clientY - r.top) / r.height) * 100,
                              mode: tool,
                              size: brushSize,
                            },
                          ]);
                        }}
                      >
                        {isMultiple ? (
                          <QuadEditor
                            imageUrl={pairImage}
                            space={[960, 480]}
                            boxes={boxes}
                            selectedIndex={selected}
                            onSelect={setSelected}
                            onChangeBox={(index, box) =>
                              setBoxes(boxes.map((old, i) => (i === index ? box : old)))
                            }
                            outlines={outlines ? "all" : "selected"}
                            labels={["Ivory", "Yam"]}
                          />
                        ) : (
                          <QuadEditor
                            imageUrl={assets.bay}
                            space={[480, 480]}
                            boxes={boxes}
                            selectedIndex={0}
                            onSelect={() => {}}
                            onChangeBox={(_, box) => setBoxes([box])}
                            outlines={outlines ? "all" : "none"}
                          />
                        )}
                        {isMultiple &&
                          boxes.map((box, index) => (
                            <img
                              key={index}
                              src={assets.artwork}
                              alt=""
                              className="mg-artwork"
                              style={{
                                left: `${(box[0].x / 960) * 100}%`,
                                top: `${(box[0].y / 480) * 100}%`,
                                width: `${((box[1].x - box[0].x) / 960) * 100}%`,
                                height: `${((box[3].y - box[0].y) / 480) * 100}%`,
                              }}
                            />
                          ))}
                        {!isMultiple && boxes[0] && (
                          <img
                            src={assets.artwork}
                            alt=""
                            className="mg-artwork"
                            style={{
                              left: `${(boxes[0][0].x / 480) * 100}%`,
                              top: `${(boxes[0][0].y / 480) * 100}%`,
                              width: `${((boxes[0][1].x - boxes[0][0].x) / 480) * 100}%`,
                              height: `${((boxes[0][3].y - boxes[0][0].y) / 480) * 100}%`,
                            }}
                          />
                        )}
                        {showMask && (
                          <svg
                            className="mg-mask-overlay"
                            viewBox={`0 0 ${isMultiple ? 960 : 480} 480`}
                            aria-label="Mask overlay: tinted areas exclude the print"
                            role="img"
                          >
                            <defs>
                              <mask id={`cloth-mask-${state}`}>
                                <rect
                                  width={isMultiple ? 960 : 480}
                                  height="480"
                                  fill={mask ? "white" : "black"}
                                />
                                {mask &&
                                  (isMultiple ? (
                                    <>
                                      <rect x="95" y="85" width="275" height="340" fill="black" />
                                      <rect x="575" y="85" width="275" height="340" fill="black" />
                                    </>
                                  ) : (
                                    <>
                                      <path d={clothOutline} fill="black" />
                                      <path
                                        d="M180 41 Q233 80 282 42 Q251 98 213 81 Z"
                                        fill="white"
                                      />
                                    </>
                                  ))}
                                {strokes.map((p, index) => (
                                  <circle
                                    key={index}
                                    cx={(p.x / 100) * (isMultiple ? 960 : 480)}
                                    cy={(p.y / 100) * 480}
                                    r={p.size / 2}
                                    fill={p.mode === "exclude" ? "white" : "black"}
                                  />
                                ))}
                              </mask>
                            </defs>
                            <rect
                              width={isMultiple ? 960 : 480}
                              height="480"
                              mask={`url(#cloth-mask-${state})`}
                              fill="#C36B4D"
                              opacity="0.32"
                            />
                            {mask && !isMultiple && (
                              <path
                                d={clothOutline}
                                fill="none"
                                stroke="#FCE9DA"
                                strokeWidth="1.5"
                                strokeDasharray="4 3"
                              />
                            )}
                          </svg>
                        )}
                        {tool !== "placement" && (
                          <span className="mg-tool-caption">
                            {tool === "exclude" ? "Exclude foreground" : "Restore cloth"}
                          </span>
                        )}
                      </div>
                      <div className="mg-canvas-foot">
                        <strong>Placement preview</strong>
                        <span>Simple overlay · open Preview to see folds and lighting.</span>
                      </div>
                      <p className="mg-canvas-hint">{currentTool}</p>
                    </>
                  ) : (
                    <div className="preview-grid">
                      <div className="preview-grid__head">
                        <span className="preview-grid__count">{"33 / 33"}</span>
                        <span className="preview-grid__status">{"Full quality"}</span>
                        <div className="preview-grid__actions">
                          <button
                            className={`btn ${renderStale ? "btn-danger" : "btn-secondary"}`}
                            disabled={!ready}
                            data-goto="marigold-v2/preview"
                          >
                            Re-render
                          </button>
                        </div>
                      </div>
                      {!ready && !rebuilding ? (
                        <div className="mg-empty-preview">
                          <ClockIcon weight="bold" />
                          <h3>Prepare the template first</h3>
                          <p>Full-quality previews need current garment maps.</p>
                          <button className="btn btn-primary" data-goto="marigold-v2/preparing">
                            Prepare template
                          </button>
                        </div>
                      ) : (
                        <>
                          <div className="preview-grid__tiles">
                            {["Bay", "Berry"].map((c) => (
                              <figure key={c} className="gallery__item preview-grid__tile">
                                <button
                                  className="preview-grid__open mg-render-open"
                                  title="Open at full size"
                                  aria-label={`Open ${c} at full size`}
                                  onClick={() => {
                                    setColour(c);
                                    setFullImage(true);
                                  }}
                                >
                                  <img src={c === "Bay" ? assets.bay : assets.berry} alt={c} />
                                  <img src={assets.artwork} alt="" className="mg-render-art" />
                                </button>
                                <figcaption>{c}</figcaption>
                              </figure>
                            ))}
                          </div>
                          <p className="mg-help">
                            Full-size renders. Click a colour to see it large.
                          </p>
                          <p className="mg-help">
                            All colours use Bay’s prepared maps. No additional preparation.
                          </p>
                        </>
                      )}
                    </div>
                  )}
                </div>
                <aside className="app__controls">
                  {prepSection}
                  <section className="realism" aria-label="Print realism">
                    <div className="realism__head">
                      <h3 className="realism__heading">Print realism</h3>
                      <button
                        className="btn btn-ghost"
                        onClick={() => {
                          setLight("Prepared garment lighting");
                          setShading(100);
                          setTexture(25);
                          setHighlights(0);
                        }}
                      >
                        Reset
                      </button>
                    </div>
                    <div className="mg-field-title">
                      <label className="mg-label" htmlFor={`lighting-${state}`}>
                        Lighting source
                      </label>
                      {infoButton("lighting")}
                    </div>
                    {infoText("lighting")}
                    <select
                      id={`lighting-${state}`}
                      className="input"
                      value={light}
                      onChange={(e) => setLight(e.target.value)}
                    >
                      <option>Prepared garment lighting</option>
                      <option>Photo-based lighting</option>
                    </select>
                    <Slider
                      label="Light & shadow strength"
                      value={shading}
                      onChange={setShading}
                      low="original design"
                      high="match cloth"
                      info={infoButton("shading")}
                    />
                    {infoText("shading")}
                    <Slider
                      label="Fabric texture"
                      value={texture}
                      onChange={setTexture}
                      low="smooth"
                      high="textured"
                      info={infoButton("texture")}
                    />
                    {infoText("texture")}
                    <Slider
                      label="Print shine"
                      value={highlights}
                      onChange={setHighlights}
                      low="matte"
                      high="shiny"
                      info={infoButton("highlights")}
                    />
                    {infoText("highlights")}
                  </section>
                  <section className="design-picker mg-design">
                    <h3 className="design-picker__heading">Test design</h3>
                    <select
                      className="input design-picker__select"
                      aria-label="Test design"
                      defaultValue="night-hike"
                    >
                      <option value="night-hike">Night Hike Club</option>
                      <option value="grid">Diagnostic grid</option>
                      <option value="white">Solid white</option>
                    </select>
                  </section>
                </aside>
              </div>
            </div>
          </div>
        </div>
      </main>
      {fullImage && (
        <div
          className="mg-lightbox"
          role="dialog"
          aria-label="Full-size preview"
          aria-modal="true"
          onKeyDown={(e) => {
            if (e.key === "Escape") setFullImage(false);
          }}
        >
          <button className="btn btn-secondary" autoFocus onClick={() => setFullImage(false)}>
            Close full-size preview
          </button>
          <div className="mg-lightbox-image">
            <img src={selectedImage} alt={`${colour} full-size mockup`} />
            <img src={assets.artwork} className="mg-render-art" alt="" />
          </div>
        </div>
      )}
    </div>
  );
}

