                  {view === "calibrate" ? (
                    <>
                      {toolbar({
                        tool,
                        setTool: (next) => {
                          setTool(next);
                          if (next !== "placement") setShowMask(true);
                        },
                        showMask,
                        setShowMask,
                        brushSize,
                        setBrushSize,
                        canUndo: brushHistory.length > 0,
                        showBox: outlines,
                        setShowBox: setOutlines,
                        undo: () => {
                          setStrokes(strokes.slice(0, brushHistory.at(-1)));
                          setBrushHistory(brushHistory.slice(0, -1));
