                            outlines={outlines ? "all" : "none"}
                            labels={["Ivory", "Yam"]}
                          />
                        ) : (
                          <QuadEditor
                            imageUrl={assets.bay}
                            space={[480, 480]}
                            boxes={boxes}
                            selectedIndex={0}
                            onSelect={() => {}}
                            onChangeBox={(_, box) => setBoxes([box])}
