                ))}
              </div>
              <div className="template-rail__filters">
                {["Colour Matrix", "Multiple", "Single"].map((kind) => (
                  <button
                    key={kind}
                    className={`tag template-rail__pill ${kindFilter === kind ? "template-rail__pill--on" : ""}`}
