                  <div className="field">
                    <label htmlFor="details-brief">Brief</label>
                    <textarea id="details-brief" value={brief} placeholder="Describe the design and include any exact words shown in it." readOnly />
                  </div>
                  <div className="seo-ai-mode-anchor">
                    <button className={busy ? "btn btn-secondary seo-ai-mode seo-ai-mode--busy" : "btn btn-secondary seo-ai-mode"} disabled={busy} type="button">
                      <SparkleIcon /> AI Mode
                    </button>
                  </div>
                  {busy && (
                    <div className="seo-ai-mode-progress">
                      <span className="seo-ai-mode-elapsed">Generating for {elapsed} seconds</span>
                      <button type="button">Cancel</button>
                    </div>
                  )}
                </div>

                <div className="field">
                  <label htmlFor="details-title">Title</label>
                  <div className="field__line">
                    <div className="field__stack">
                      <input id="details-title" className="input" value={title} readOnly />
                      {open.title && (
                        <AiChoiceDrawer field="title" options={titles} stale={false} rationale={[]} warnings={[]} observedText="Take A Hike"
                          onChoose={(v) => { setTitle(v); setOpen((o) => ({ ...o, title: false })); }}
                          onReject={() => setOpen((o) => ({ ...o, title: false }))} />
                      )}
                    </div>
                    <span className="field__count">{title.length} / 140</span>
                  </div>
                </div>

                <div className="field">
                  <label htmlFor="details-tag-draft">Tags</label>
                  <div className="chips">
                    {tags.map((t) => <span key={t} className="chip">{t}<span className="chip__x" onClick={() => toggleTag(t)}>×</span></span>)}
                    {tags.length === 0 && <span className="chips__empty">No tags yet</span>}
                  </div>
                  <div className="field__line">
                    <div className="field__stack">
                      <input id="details-tag-draft" className="input tag-paste" placeholder="Type or paste tags, comma separated — press Enter to add" readOnly />
                      {open.tags && (
                        <AiTagsDrawer tags={tagPool} selected={tags} stale={false} rationale={[]} warnings={[]} observedText="Take A Hike"
                          onToggle={toggleTag}
                          onAcceptBest={() => { setTags(tagPool.slice(0, 13)); setOpen((o) => ({ ...o, tags: false })); }}
                          onClose={() => setOpen((o) => ({ ...o, tags: false }))} />
                      )}
                    </div>
                    <span className="field__count">{tags.length} / 13</span>
                  </div>
                </div>

                <div className="field">
                  <label htmlFor="details-description-lead">Description Lead</label>
                  <textarea id="details-description-lead" value={lead} readOnly />
                  {open.lead && (
                    <AiChoiceDrawer field="description lead" options={leads} stale={false} rationale={[]} warnings={[]} observedText="Take A Hike"
                      onChoose={(v) => { setLead(v); setOpen((o) => ({ ...o, lead: false })); }}
                      onReject={() => setOpen((o) => ({ ...o, lead: false }))} />
                  )}
                </div>

                <div className="field">
                  <label htmlFor="details-section">Section</label>
                  <select id="details-section" className="input" defaultValue="Graphic Tees"><option>Graphic Tees</option><option>Outdoor Gifts</option></select>
                </div>
                <div className="field">
                  <label htmlFor="details-materials">Materials</label>
                  <input id="details-materials" className="input" value="ring-spun cotton" readOnly />
                  <span className="field__hint">Set by the selected garment profile.</span>
                </div>
              </fieldset>
            </div>

            <MarketListingsPanel {...panel} />
          </div>
        </div>
      </main>
    </div>
  );
}

import { CaretDownIcon } from "@phosphor-icons/react/dist/csr/CaretDown";
import { LinkBreakIcon } from "@phosphor-icons/react/dist/csr/LinkBreak";
import { LinkSimpleIcon } from "@phosphor-icons/react/dist/csr/LinkSimple";
import { cap, listNames, slotUsers, TILE, toneLabel, type Base, type Colour, type Design, type Tone } from "./artwork";
import type { PickTarget } from "./ArtworkEditorScreen";

/** Base slots offer this many before the full list is needed -- the same
 * four the design strip offers today. */
const RECENT = 4;

export type SlotTarget = Exclude<PickTarget, { kind: "colour" }>;

const sameTarget = (a: SlotTarget | null, b: SlotTarget) =>
  a !== null && a.kind === b.kind && (a.kind === "one" || (b.kind === "slot" && a.tone === b.tone));

/**
 * The design strip above the tabs: always two cards, for light and for dark
 * shirts, joined by a link. Linked is one design (`design.default`) -- the
 * dark card mirrors the light one. Unlinking, or choosing a different file for
 * dark shirts, splits them into `on-light` / `on-dark`; linking again asks
 * which file to keep.
 */
export function ArtworkStrip({
  base,
  colours,
  library,
  open,
  setOpen,
  onLink,
  onUnlink,
  onPick,
  onFind,
  onPreview,
}: {
  base: Base;
  colours: Colour[];
  library: Design[];
  /** The slot whose Recent designs panel is open -- held by the screen, so
   * the preview card can open it too. */
  open: SlotTarget | null;
  setOpen: (t: SlotTarget | null) => void;
  onLink: () => void;
  onUnlink: () => void;
  onPick: (target: PickTarget, design: Design) => void;
  /** Opens the full design list for a target. */
  onFind: (target: PickTarget) => void;
  onPreview: (name: string) => void;
}) {
  const own = colours.filter((c) => c.enabled && c.own !== null);
  const split = base.mode === "light-dark";
  const toggleOpen = (t: SlotTarget) => setOpen(sameTarget(open, t) ? null : t);
  const users = (tone: Tone) => slotUsers(colours, tone).map((c) => c.name);

  const current = (t: SlotTarget): Design | null =>
    t.kind === "one" ? (base.mode === "one" ? base.design : null) : base.mode === "light-dark" ? base[t.tone] : base.design;

  // Linked, the light card is the one design for every shirt.
  const lightTarget: SlotTarget = split ? { kind: "slot", tone: "light" } : { kind: "one" };
  const darkTarget: SlotTarget = { kind: "slot", tone: "dark" };

  // Linked, the light card's design prints on every shirt, and says so; the
  // dark card only mirrors it.
  const everyShirt = own.length > 0 ? "Prints on every colour without its own design" : "Prints on every colour you sell";
  const slot = (t: SlotTarget, tone: Tone, mirrored: boolean) => (
    <Slot
      title={!split && tone === "light" ? "For all shirts" : `For ${toneLabel(tone)}`}
      design={current(t)}
      tile={TILE[tone]}
      users={users(tone)}
      usedBy={
        split ? null : tone === "light" ? everyShirt : "Same as all shirts"
      }
      open={sameTarget(open, t)}
      missing={split && current(t) === null && users(tone).length > 0}
      mirrored={mirrored}
      emptyText={split ? `Choose the design for ${toneLabel(tone)}` : "No design selected"}
      onChange={() => toggleOpen(t)}
    />
  );

  return (
    <div className="design-select ma-strip">
      {own.length > 0 && (
        <div className="ma-strip__head">
          <span className="ma-strip__own">
            Also printing their own design:{" "}
            {own.map((c, i) => (
              <span key={c.name}>
                {i > 0 && ", "}
                <button type="button" className="ma-link" onClick={() => onPreview(c.name)}>
                  {cap(c.name)}
                </button>
              </span>
            ))}
          </span>
        </div>
      )}

      <div className="ma-slots ma-slots--linked">
        {slot(lightTarget, "light", false)}
        <button
          type="button"
          className={split ? "ma-chain" : "ma-chain ma-chain--on"}
          aria-pressed={!split}
          title={split ? "Use one design for all shirts" : "Use a different design for dark shirts"}
          onClick={() => {
            setOpen(null);
            if (split) onLink();
            else onUnlink();
          }}
        >
          {split ? <LinkSimpleIcon weight="bold" aria-hidden="true" /> : <LinkBreakIcon weight="bold" aria-hidden="true" />}
          <span>{split ? "Link" : "Unlink"}</span>
        </button>
        {slot(darkTarget, "dark", !split)}
      </div>

      {open !== null && (
        <div className="add-panel ma-recent">
          <span className="section-label">
            Recent designs{open.kind === "slot" ? ` for ${toneLabel(open.tone)}` : " for all shirts"}
          </span>
          <div className="template-grid">
            {library.slice(0, RECENT).map((d) => (
              <button
                key={d.file}
                type="button"
                className={current(open)?.file === d.file ? "template-card template-card--active" : "template-card"}
                onClick={() => {
                  onPick(open, d);
                  setOpen(null);
                }}
              >
                <span className="template-card__name">{d.name}</span>
                <span className="template-card__kind">{d.file}</span>
              </button>
            ))}
          </div>
          <button
            type="button"
            className="btn-like btn-like--ghost btn-sm"
            onClick={() => {
              onFind(open);
              setOpen(null);
            }}
          >
            Find a design…
          </button>
        </div>
      )}
    </div>
  );
}

function Slot({
  title,
  design,
  tile,
  users,
  usedBy: usedByText,
  open,
  missing,
  mirrored,
  emptyText,
  onChange,
}: {
  title: string;
  design: Design | null;
  tile: string;
  users: string[];
  /** Overrides the "Prints on …" line -- linked, both cards speak for every shirt. */
  usedBy: string | null;
  open: boolean;
  missing: boolean;
  /** Linked: showing the light card's file, not its own. */
  mirrored: boolean;
  emptyText: string;
  onChange: () => void;
}) {
  const usedBy = usedByText ?? (users.length === 0 ? "Not used — no colour you sell needs it" : `Prints on ${listNames(users)}`);
  const cls = ["design-row", "ma-slot", missing ? "ma-slot--missing" : "", mirrored ? "ma-slot--mirrored" : "", open ? "ma-slot--open" : ""]
    .filter(Boolean)
    .join(" ");
  return (
    <div className={cls}>
      {design !== null ? (
        <span className="design-thumb ma-tile" style={{ background: tile }}>
          <img src={design.url} alt="" />
        </span>
      ) : (
        <span className="design-thumb design-thumb--empty ma-tile--empty" />
      )}
      <div className="design-row__text">
        <div className="ma-slot__title">{title}</div>
        {design !== null ? (
          <div className="design-row__name">
            {design.name}
            {mirrored && <span className="ma-slot__same"> · linked</span>}
          </div>
        ) : (
          <div className="design-row__name design-row__name--empty">{emptyText}</div>
        )}
        <div className={usedByText === null && users.length === 0 ? "ma-slot__users ma-slot__users--idle" : "ma-slot__users"}>{usedBy}</div>
      </div>
      <button type="button" className="design-row__change" aria-expanded={open} onClick={onChange}>
        {mirrored ? "Use a different one" : design === null ? "Choose" : "Change"} <CaretDownIcon weight="bold" aria-hidden="true" />
      </button>
    </div>
  );
}

import { useState } from "react";
import { CheckIcon } from "@phosphor-icons/react/dist/csr/Check";
import { MagnifyingGlassIcon } from "@phosphor-icons/react/dist/csr/MagnifyingGlass";
import {
  cap,
  listNames,
  resolve,
  resolvedDesign,
  slotUsers,
  TILE,
  toneLabel,
  type Base,
  type Colour,
  type Design,
  type Tone,
} from "./artwork";
import type { PickTarget } from "./ArtworkEditorScreen";

/* ── picking a file from the design library ───────────────────────────────── */

export function ArtworkPicker({
  target,
  base,
  colours,
  library,
  onPick,
  onClose,
}: {
  target: PickTarget;
  base: Base;
  colours: Colour[];
  library: Design[];
  onPick: (d: Design) => void;
  onClose: () => void;
}) {
  const [query, setQuery] = useState("");
  let title: string;
  let hint: string;
  let tile: string;
  let current: Design | null;
  if (target.kind === "colour") {
    const colour = colours.find((c) => c.name === target.name) as Colour;
    const siblings = colours.filter(
      (c) => c.enabled && c.own === null && c.name !== colour.name && (base.mode === "one" || c.tone === colour.tone),
    );
    title = `Design for ${cap(colour.name)}`;
    hint =
      `Only ${cap(colour.name)} changes.` +
      (siblings.length > 0
        ? ` ${listNames(siblings.map((c) => c.name))} keep${siblings.length === 1 ? "s" : ""} ${base.mode === "one" ? "the design for all shirts" : colour.tone === null ? "their design" : `the design for ${toneLabel(colour.tone)}`}.`
        : "");
    tile = colour.swatch;
    current = resolvedDesign(resolve(colour, base));
  } else if (target.kind === "slot") {
    title = `Design for ${toneLabel(target.tone)}`;
    const users = slotUsers(colours, target.tone);
    hint = users.length > 0 ? `Prints on ${listNames(users.map((c) => c.name))}.` : "No colour you sell uses it right now.";
    tile = TILE[target.tone];
    current = base.mode === "light-dark" ? base[target.tone] : null;
  } else {
    title = "Design for all shirts";
    hint = "Every colour prints it, apart from any with their own design.";
    tile = TILE.neutral;
    current = base.mode === "one" ? base.design : null;
  }
  const matches = library.filter((d) => d.name.includes(query.toLowerCase()));

  return (
    <div className="modal-root" role="dialog" aria-modal="true" aria-label={title}>
      <div className="modal-backdrop" onClick={onClose} aria-hidden="true" />
      <div className="modal-dialog ma-picker">
        <div className="modal-dialog__head">
          <h2 className="modal-dialog__title">{title}</h2>
          <button type="button" className="modal-dialog__close" aria-label="Close" onClick={onClose}>
            ×
          </button>
        </div>
        <p className="ma-picker__hint">{hint}</p>
        <div className="ma-search">
          <MagnifyingGlassIcon weight="bold" aria-hidden="true" />
          <input
            className="input"
            type="text"
            placeholder="Search your designs…"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
        <div className="modal-dialog__list">
          {matches.map((d) => {
            const on = current?.file === d.file;
            return (
              <button
                key={d.file}
                type="button"
                className={on ? "modal-design-row ma-pick ma-pick--on" : "modal-design-row ma-pick"}
                onClick={() => onPick(d)}
              >
                <span className="modal-design-row__thumb ma-tile" style={{ background: tile }}>
                  <img src={d.url} alt="" />
                </span>
                <span className="ma-pick__text">
                  <span className="modal-design-row__name">{d.name}</span>
                  <span className="modal-design-row__file">{d.file}</span>
                </span>
                {on && (
                  <span className="ma-pick__current">
                    <CheckIcon weight="bold" aria-hidden="true" /> Current
                  </span>
                )}
              </button>
            );
          })}
          {matches.length === 0 && <p className="modal-empty">No designs match your search</p>}
        </div>
      </div>
    </div>
  );
}

/* ── leaving light/dark ──────────────────────────────────────────────────── */

export function BackToOneDialog({
  base,
  colours,
  onKeep,
  onCancel,
}: {
  base: Extract<Base, { mode: "light-dark" }>;
  colours: Colour[];
  onKeep: (d: Design) => void;
  onCancel: () => void;
}) {
  const [choice, setChoice] = useState<Tone | null>(null);
  const own = colours.filter((c) => c.enabled && c.own !== null);
  return (
    <div className="modal-root" role="dialog" aria-modal="true" aria-labelledby="ma-leave-title">
      <div className="modal-backdrop" onClick={onCancel} aria-hidden="true" />
      <div className="modal-dialog confirm-dialog ma-leave">
        <h2 id="ma-leave-title" className="confirm-dialog__title">
          Which design should every shirt print?
        </h2>
        <p className="ma-leave__body">
          Pick the one to keep. The other stays in your design library.
        </p>
        <div className="ma-leave__options" role="radiogroup" aria-label="Design to keep">
          {(["light", "dark"] as const).map((tone) => {
            const d = base[tone] as Design;
            const on = choice === tone;
            return (
              <button
                key={tone}
                type="button"
                role="radio"
                aria-checked={on}
                className={on ? "template-card template-card--active ma-keep" : "template-card ma-keep"}
                onClick={() => setChoice(tone)}
              >
                <span className="design-thumb ma-tile" style={{ background: TILE[tone] }}>
                  <img src={d.url} alt="" />
                </span>
                <span className="ma-keep__text">
                  <span className="template-card__name">{d.name}</span>
                  <span className="template-card__kind">Now the design for {toneLabel(tone)}</span>
                </span>
              </button>
            );
          })}
        </div>
        {own.length > 0 && (
          <p className="ma-leave__note">
            {listNames(own.map((c) => c.name))} keep{own.length === 1 ? "s" : ""} {own.length === 1 ? "its" : "their"} own design.
          </p>
        )}
        <div className="confirm-dialog__actions">
          <button type="button" className="btn btn-ghost" onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-secondary"
            disabled={choice === null}
            onClick={() => choice !== null && onKeep(base[choice] as Design)}
          >
            Use one design
          </button>
        </div>
      </div>
    </div>
  );
}

import { ShirtPreview } from "./ShirtPreview";
import {
  cap,
  resolve,
  resolvedDesign,
  toneLabel,
  type Base,
  type Colour,
  type Resolution,
  type Tone,
} from "./artwork";

/**
 * The real `VariantsTab` (src/pages/editor/VariantsTab.tsx), forked to take
 * fixture props instead of fetching, plus the multi-artwork parts: each row's
 * artwork chip and the "what this colour prints" card under the stage.
 * Everything else -- garment select, sizes, the shade buttons, rows, the
 * stage and its hint -- is the real markup.
 */
export function VariantsArtworkTab({
  profile,
  sizes,
  colours,
  base,
  previewed,
  status,
  onPreview,
  onToggle,
  onOnlyShade,
  onPickColour,
  onPickSlot,
  onAutomatic,
}: {
  profile: string;
  sizes: string[];
  colours: Colour[];
  base: Base;
  previewed: string;
  status: string;
  onPreview: (name: string) => void;
  onToggle: (name: string) => void;
  onOnlyShade: (tone: Tone) => void;
  onPickColour: (name: string) => void;
  onPickSlot: (tone: Tone) => void;
  onAutomatic: (name: string) => void;
}) {
  const shown = colours.find((c) => c.name === previewed) ?? colours[0];
  const enabled = colours.filter((c) => c.enabled).length;
  const hasShades = colours.some((c) => c.tone !== null);

  return (
    <div className="layout--variants">
      <fieldset>
        <legend>Variants</legend>

        <div className="field">
          <label htmlFor="variants-garment">Garment profile</label>
          <select id="variants-garment" defaultValue={profile}>
            <option value={profile}>{profile}</option>
          </select>
        </div>

        <div className="field">
          <label>Sizes</label>
          <div className="garment-card__sizes">
            {sizes.map((size) => (
              <span key={size} className="size-pill">
                {size}
              </span>
            ))}
          </div>
        </div>

        <div className="field">
          <div className="colors-panel__head">
            <label style={{ margin: 0 }}>Colours</label>
            <span className="colors-panel__count">
              {enabled} of {colours.length} included
            </span>
          </div>

          {hasShades && (
            <div className="shade-picker">
              <button type="button" className="btn-like btn-sm" onClick={() => onOnlyShade("dark")}>
                Dark
              </button>
              <button type="button" className="btn-like btn-sm" onClick={() => onOnlyShade("light")}>
                Light
              </button>
              <span className="shade-picker__hint">only these shades</span>
            </div>
          )}

          {colours.map((colour) => (
            <ColourRow
              key={colour.name}
              colour={colour}
              resolution={resolve(colour, base)}
              selected={colour.name === shown.name}
              onPreview={() => onPreview(colour.name)}
              onToggle={() => onToggle(colour.name)}
              onPick={() => onPickColour(colour.name)}
            />
          ))}
        </div>
      </fieldset>

      <div className="variants-preview">
        <div className="preview-stage preview-stage--large ma-stage">
          <ShirtPreview
            colour={shown.swatch}
            artwork={resolvedDesign(resolve(shown, base))?.url ?? null}
            label={`${shown.name} on the preview template`}
          />
        </div>
        <PrintsCard
          colour={shown}
          resolution={resolve(shown, base)}
          base={base}
          profile={profile}
          onPick={() => onPickColour(shown.name)}
          onPickSlot={onPickSlot}
          onAutomatic={() => onAutomatic(shown.name)}
        />
        <p className="variants-preview__hint">
          Click a colour to preview it — helps judge whether it suits the design.
        </p>
        <p role="status" className="app__status">
          {status}
        </p>
      </div>
    </div>
  );
}

/* ── Variants rows and the card under the preview ─────────────────────────── */

function ColourRow({
  colour,
  resolution,
  selected,
  onPreview,
  onToggle,
  onPick,
}: {
  colour: Colour;
  resolution: Resolution;
  selected: boolean;
  onPreview: () => void;
  onToggle: () => void;
  onPick: () => void;
}) {
  const design = resolvedDesign(resolution);
  const rowClass = ["color-row", selected ? "color-row--selected" : "", colour.enabled ? "" : "color-row--off"]
    .filter(Boolean)
    .join(" ");
  return (
    <div className={rowClass}>
      <button type="button" className="color-row__text" aria-label={`Preview ${colour.name}`} onClick={onPreview}>
        <span className="color-row__swatch" style={{ background: colour.swatch }} aria-hidden="true" />
        <span className="color-row__name">{colour.name}</span>
        {resolution.kind === "own" && colour.enabled && <span className="tag tag-accent-2 ma-own-tag">own design</span>}
      </button>
      {colour.enabled && (
        <button
          type="button"
          className={[
            "ma-chip",
            resolution.kind === "own" ? "ma-chip--own" : "",
            design === null ? "ma-chip--empty" : "",
          ]
            .filter(Boolean)
            .join(" ")}
          style={design !== null ? { background: colour.swatch } : undefined}
          aria-label={`Select different design for ${colour.name}`}
          title="Select different design"
          onClick={onPick}
        >
          {design !== null && <img src={design.url} alt="" />}
        </button>
      )}
      {colour.tone !== null ? (
        <span className={colour.tone === "dark" ? "tag tag-neutral" : "tag tag-accent"}>{colour.tone}</span>
      ) : (
        <span className="tag tag-dirty">no tone</span>
      )}
      <button
        type="button"
        role="switch"
        aria-checked={colour.enabled}
        aria-label={colour.name}
        className={colour.enabled ? "switch switch--on" : "switch"}
        onClick={onToggle}
      >
        <span className="switch__knob" />
      </button>
    </div>
  );
}

function PrintsCard({
  colour,
  resolution,
  base,
  profile,
  onPick,
  onPickSlot,
  onAutomatic,
}: {
  colour: Colour;
  resolution: Resolution;
  base: Base;
  profile: string;
  onPick: () => void;
  onPickSlot: (tone: Tone) => void;
  onAutomatic: () => void;
}) {
  const name = cap(colour.name);
  if (!colour.enabled) {
    return <p className="variants-preview__hint">{name} isn&rsquo;t sold on this listing. Switch it on to choose what it prints.</p>;
  }

  let title: string;
  let why: string;
  if (resolution.kind === "unclassified") {
    title = `${name} can’t pick a design yet`;
    why = `The ${profile} garment profile doesn’t say whether ${colour.name} is a light or dark shirt. Mark it in garment-profiles/${profile}.yaml — this listing can’t decide it.`;
  } else if (resolution.kind === "own") {
    const fallback = base.mode === "one" ? base.design : colour.tone === null ? null : base[colour.tone];
    title = `${name} prints ${resolution.design.name}`;
    why =
      `Its own design, for ${name} only.` +
      (fallback !== null
        ? ` Back on automatic it would print ${fallback.name}${base.mode === "light-dark" && colour.tone !== null ? `, the design for ${toneLabel(colour.tone)}` : ""}.`
        : "");
  } else if (resolution.design === null) {
    title = `${name} has nothing to print`;
    why =
      resolution.kind === "slot"
        ? `It’s a ${resolution.tone} shirt, and no design for ${toneLabel(resolution.tone)} is chosen yet.`
        : "Choose a design above.";
  } else {
    title = `${name} prints ${resolution.design.name}`;
    why =
      resolution.kind === "slot"
        ? `Automatic: the design for ${toneLabel(resolution.tone)}, because ${profile} marks ${colour.name} ${resolution.tone}.`
        : "Automatic: the one design for all shirts.";
  }

  const design = resolvedDesign(resolution);
  return (
    <div className={resolution.kind === "unclassified" ? "ma-prints ma-prints--blocked" : "ma-prints"}>
      {design !== null ? (
        <span className="ma-prints__thumb" style={{ background: colour.swatch }}>
          <img src={design.url} alt="" />
        </span>
      ) : (
        <span className="ma-prints__thumb ma-tile--empty" />
      )}
      <div className="ma-prints__text">
        <div className="ma-prints__title">{title}</div>
        <div className="ma-prints__why">{why}</div>
        {design !== null && <div className="ma-prints__note">Listing Images and Printify use this same file.</div>}
      </div>
      {resolution.kind !== "unclassified" && (
        <div className="ma-prints__actions">
          {resolution.kind === "own" ? (
            <>
              <button type="button" className="btn-like btn-sm ma-btn" onClick={onPick}>
                Change
              </button>
              <button type="button" className="btn-like btn-like--ghost btn-sm ma-btn" onClick={onAutomatic}>
                Use automatic design
              </button>
            </>
          ) : resolution.kind === "slot" && resolution.design === null ? (
            <>
              <button type="button" className="btn-like btn-like--primary btn-sm ma-btn" onClick={() => onPickSlot(resolution.tone)}>
                Choose design for {toneLabel(resolution.tone)}
              </button>
              <button type="button" className="btn-like btn-like--ghost btn-sm ma-btn" onClick={onPick}>
                Select different design for {name}
              </button>
            </>
          ) : (
            <button type="button" className="btn-like btn-sm ma-btn" onClick={onPick}>
              Select different design
            </button>
          )}
        </div>
      )}
    </div>
  );
}

import type { Issue } from "../../../src/types";

/** One file in the workspace design library. */
export interface Design {
  name: string;
  file: string;
  url: string;
}

export type Tone = "light" | "dark";

/** A colour the garment profile offers. `tone` is `null` when the profile has
 * not classified it -- shared garment data, never fixed from the listing. */
export interface Colour {
  name: string;
  swatch: string;
  tone: Tone | null;
  enabled: boolean;
  /** A direct `design[colour]` exception. */
  own: Design | null;
}

/** The reserved base keys of `design`, as the editor holds them. */
export type Base =
  | { mode: "one"; design: Design | null }
  | { mode: "light-dark"; light: Design | null; dark: Design | null };

/** Where a colour's file came from, which is what its row and the preview
 * card explain. */
export type Resolution =
  | { kind: "own"; design: Design }
  | { kind: "one"; design: Design | null }
  | { kind: "slot"; tone: Tone; design: Design | null }
  | { kind: "unclassified" };

export function resolve(colour: Colour, base: Base): Resolution {
  if (colour.own !== null) return { kind: "own", design: colour.own };
  if (base.mode === "one") return { kind: "one", design: base.design };
  if (colour.tone === null) return { kind: "unclassified" };
  return { kind: "slot", tone: colour.tone, design: base[colour.tone] };
}

export function resolvedDesign(r: Resolution): Design | null {
  return r.kind === "unclassified" ? null : r.design;
}

export const toneLabel = (tone: Tone) => (tone === "light" ? "light shirts" : "dark shirts");

export function listNames(names: string[]): string {
  const cap = names.map((n) => n[0].toUpperCase() + n.slice(1));
  if (cap.length <= 1) return cap.join("");
  return `${cap.slice(0, -1).join(", ")} and ${cap[cap.length - 1]}`;
}

/** Automatic enabled colours of one tone -- the colours that need that base
 * slot once direct exceptions are taken out. */
export function slotUsers(colours: Colour[], tone: Tone): Colour[] {
  return colours.filter((c) => c.enabled && c.own === null && c.tone === tone);
}

/** The server's validation, re-stated for the mockup: incomplete states block
 * deploying, the one-slot case only warns. */
export function artworkIssues(base: Base, colours: Colour[], profile: string): Issue[] {
  const issues: Issue[] = [];
  const enabled = colours.filter((c) => c.enabled);

  const noBase = base.mode === "one" ? base.design === null : base.light === null && base.dark === null;
  if (noBase) {
    issues.push({
      message: "No design is chosen for this listing yet",
      severity: "block",
      tab: "variants",
      where: "Artwork",
    });
  }

  const unclassified = enabled.filter((c) => c.tone === null);
  if (unclassified.length > 0) {
    issues.push({
      message: `${listNames(unclassified.map((c) => c.name))} ${unclassified.length === 1 ? "isn't" : "aren't"} marked light or dark in the ${profile} garment profile`,
      severity: "block",
      tab: "variants",
      where: `Fix it in garment-profiles/${profile}.yaml`,
    });
  }

  if (base.mode === "light-dark" && !noBase) {
    const used: Tone[] = [];
    for (const tone of ["light", "dark"] as const) {
      const users = slotUsers(colours, tone);
      if (users.length === 0) continue;
      used.push(tone);
      if (base[tone] === null) {
        issues.push({
          message: `${listNames(users.map((c) => c.name))} ${users.length === 1 ? `is a ${tone} shirt` : `are ${tone} shirts`}, but no design for ${toneLabel(tone)} is chosen`,
          severity: "block",
          tab: "variants",
          where: `Artwork · For ${toneLabel(tone)}`,
        });
      }
    }
    if (used.length === 1) {
      const other: Tone = used[0] === "light" ? "dark" : "light";
      issues.push({
        message: `Only the design for ${toneLabel(used[0])} is in use — no ${other} shirt you sell needs the design for ${toneLabel(other)}`,
        severity: "warn",
        tab: "variants",
        where: "Artwork · Link the two designs if one is all this listing needs",
      });
    }
  }

  return issues;
}

/** Cloth shown behind a thumbnail: artwork is judged on the shirt it is for. */
export const TILE = { light: "#efe6d2", dark: "#262626", neutral: "var(--color-neutral-200)" };

export const cap = (s: string) => s[0].toUpperCase() + s.slice(1);

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { listTemplates } from "./api/calibrator";
import { InferenceSettings } from "./components/InferenceSettings";
import { KindPicker } from "./components/KindPicker";
import { preparationLabel, marigoldMapsReady } from "./components/preparationLabel";
import { RendererPanel } from "./components/RendererPanel";
import { TemplateRail } from "./components/TemplateRail";
import { ColourMatrixEditor } from "./editors/ColourMatrixEditor";
import { MARIGOLD_DEFAULTS } from "./editors/marigoldDefaults";
import { MarigoldEditor } from "./editors/MarigoldEditor";
import { MultipleEditor } from "./editors/MultipleEditor";
import { SingleEditor } from "./editors/SingleEditor";
import { usePreparationQueue } from "./hooks/usePreparationQueue";
import { useTemplateReadiness } from "./hooks/useTemplateReadiness";
import { useTemplateSession } from "./hooks/useTemplateSession";
import { SavedAgo } from "./pages/editor/SavedAgo";
import type { Renderer, TemplateKind, TemplateSummary } from "./types";

/** A thin router: picks the template, hands it to an authoring session
 * (`useTemplateSession`, which reads, saves and prepares it) and picks an
 * editor by `kind` -- a template.yaml is exactly one of three shapes, never a
 * mix.
 *
 * Wireframe 2a turns the page into a workbench: the rail on the left picks the
 * template (replacing the dropdown that used to sit in the header), and the
 * header becomes a breadcrumb saying what is open, whether it is finished, and
 * what it holds. */

const KIND_LABELS: Record<TemplateKind, string> = {
  "colour-matrix": "Colour Matrix",
  multiple: "Multiple",
  single: "Single",
};

export function App() {
  const preparationJobs = usePreparationQueue();
  const rendererCache = useRef<Record<string, Partial<Record<Renderer["type"], Renderer>>>>({});
  const [templates, setTemplates] = useState<TemplateSummary[]>([]);
  const [catalogState, setCatalogState] = useState<"loading" | "ready" | "error">("loading");
  const [templateName, setTemplateName] = useState<string | null>(null);
  // Which test artwork the previews render with. A way of looking at a
  // template rather than a property of one, so it lives here and never enters
  // template.yaml -- and it deliberately survives switching template, since
  // "show me all of these against my real artwork" is the point of changing it.
  const [design, setDesign] = useState("bundled-grid");

  // Refreshes overlap: assigning a kind fires one and saving fires another
  // moments later. They are separate requests, so the *older* can resolve
  // last -- putting the pre-assignment list back and reverting the template to
  // "no kind set" on screen while the file on disk says otherwise. The
  // sequence number makes a late response a no-op instead.
  const refreshSeq = useRef(0);
  const currentTemplate = useRef<string | null>(templateName);

  useEffect(() => {
    currentTemplate.current = templateName;
  }, [templateName]);

  const refreshTemplates = useCallback((selectName?: string) => {
    const seq = ++refreshSeq.current;
    const selectionAtRequest = currentTemplate.current;
    listTemplates()
      .then((loaded) => {
        if (seq !== refreshSeq.current) return;
        setCatalogState("ready");
        setTemplates(loaded);
        // A save may finish its catalog refresh after the user has moved on.
        setTemplateName(
          (current) =>
            (current === selectionAtRequest ? selectName : undefined) ??
            current ??
            loaded[0]?.name ??
            null,
        );
      })
      .catch(() => {
        if (seq !== refreshSeq.current) return;
        setCatalogState("error");
      });
  }, []);

  useEffect(() => {
    refreshTemplates();
  }, [refreshTemplates]);

  const session = useTemplateSession(templateName, { onCatalogChanged: refreshTemplates });
  const { config, preparation, preparing, save, update: setConfig, reloadPreparation } = session;

  const mapState = preparation?.maps.state;
  useEffect(() => {
    if (mapState) refreshTemplates();
  }, [mapState, refreshTemplates]);

  const switchRenderer = (type: Renderer["type"]) => {
    if (!config || !templateName || type === config.renderer.type) return;
    const cache = rendererCache.current[templateName] ?? {};
    cache[config.renderer.type] = config.renderer;
    rendererCache.current[templateName] = cache;
    const stored = preparation?.renderer_settings[type];
    const renderer =
      cache[type] ??
      (stored
        ? ({ type, config: stored } as Renderer)
        : type === "marigold"
          ? MARIGOLD_DEFAULTS
          : {
              type: "photo-warp",
              config: {
                displace: { enabled: false, strength: 0 },
                shade: { enabled: true, opacity: 0.6, blend: "soft-light" },
              },
            });
    setConfig({ ...config, renderer });
  };
  const queueKey = preparationJobs
    .filter((job) => job.template === templateName)
    .map((job) => job.id + job.phase)
    .join(",");
  const previousQueueKey = useRef(queueKey);
  useEffect(() => {
    if (previousQueueKey.current !== queueKey) reloadPreparation();
    previousQueueKey.current = queueKey;
  }, [queueKey, reloadPreparation]);
  const railFacts = useTemplateReadiness(templates, templateName, preparationJobs);
  const railTemplates = useMemo(
    () =>
      templates.map((template) =>
        preparation?.template === template.name
          ? { ...template, maps: preparation.maps }
          : { ...template, maps: railFacts[template.name] ?? template.maps ?? null },
      ),
    [templates, preparation, railFacts],
  );
  const selected = templates.find((t) => t.name === templateName);
  const rendererControls =
    config && templateName ? (
      <RendererPanel
        renderer={config.renderer}
        onRendererChange={switchRenderer}
        preparation={preparation}
        onPrepare={(action, recovery) => void session.prepare(action, recovery)}
        onCancel={() => void session.cancelPreparation()}
        pending={preparing}
        error={session.preparationError}
        settings={(runtime) =>
          config.renderer.type === "marigold" ? (
            <InferenceSettings
              templateName={templateName}
              value={config.renderer.config.inference}
              capabilityKnown={Boolean(runtime)}
              {...(runtime
                ? {
                    limits: {
                      num_inference_steps: runtime.max_num_inference_steps,
                      ensemble_size: runtime.max_ensemble_size,
                    },
                  }
                : {})}
              onSave={(inference) => {
                if (config.renderer.type === "marigold")
                  setConfig({
                    ...config,
                    renderer: {
                      ...config.renderer,
                      config: { ...config.renderer.config, inference },
                    },
                  });
              }}
            />
          ) : null
        }
      />
    ) : null;

  // Every colour already in use anywhere in the workspace, for the box
  // colour field's suggestions. Suggestions rather than a closed list: a
  // chart's colours are whatever the listing sells, and nothing here knows
  // that -- wiring in the Printify catalog would be a much larger dependency.
  const knownColours = useMemo(
    () => [...new Set(templates.flatMap((t) => t.colours))].filter(Boolean).sort(),
    [templates],
  );
  const kindLabel = selected?.kind ? KIND_LABELS[selected.kind] : null;

  // The photo's true pixel size, which is the coordinate space every bounding
  // box in template.yaml is written in. It has to come from the API: the
  // editors' canvas renders a downscale now, so measuring the image on screen
  // would put the boxes in the preview's space and save them several times too
  // small. `null` for a directory with no readable photo -- there is nothing
  // to calibrate against, and the editors say so rather than guessing.
  const space: [number, number] | null =
    selected?.width && selected.height ? [selected.width, selected.height] : null;

  return (
    <div className={config?.renderer.type === "marigold" ? "app mg-frame mg-app" : "app mg-frame"}>
      <header className="app__header">
        <h1 className="app__title">Mockup Templates</h1>
        {selected && (
          <>
            <span className="app__crumb-sep">/</span>
            <span className="app__crumb">{selected.name}</span>
            {config && config.renderer.type !== "marigold" && (
              <span
                className={selected.status === "calibrated" ? "tag tag-accent-2" : "tag tag-accent"}
              >
                {selected.status === "calibrated" ? "calibrated" : "needs calibration"}
              </span>
            )}
            {config?.renderer.type === "marigold" && (
              <span
                className={
                  "tag mg-status" +
                  (!preparing && marigoldMapsReady(preparation?.maps)
                    ? " mg-status--ready"
                    : preparation?.latest_job?.phase === "failed"
                      ? " mg-status--failed"
                      : "")
                }
              >
                {preparing ? "Preparing" : preparationLabel(preparation)}
              </span>
            )}
            <span className="app__meta">
              {config?.kind === "multiple"
                ? "Multiple · " + config.placements.length + " placements"
                : selected.status === "calibrated"
                  ? `${kindLabel ?? "Unknown"} · ${selected.colours.length} colour${
                      selected.colours.length === 1 ? "" : "s"
                    }`
                  : (selected.status_reason ?? "not calibrated")}
            </span>
          </>
        )}

        <div className="app__actions">
          <p className="app__status" role="status">
            {save.kind === "saved" ? (
              <span className="page-head__saved">
                <span className="page-head__dot" aria-hidden="true" />
                <SavedAgo savedAt={save.savedAt} />
              </span>
            ) : save.kind === "saving" ? (
              "Saving…"
            ) : save.kind === "failed" || save.kind === "conflict" ? (
              save.message
            ) : session.load === "error" ? (
              "failed to load template config"
            ) : catalogState === "error" ? (
              "failed to load templates"
            ) : (
              ""
            )}
          </p>
          {save.kind === "conflict" && <button onClick={session.reload}>Reload template</button>}
        </div>
      </header>

      <div className="app__workbench">
        <TemplateRail
          templates={railTemplates}
          selectedPreparationStatus={
            config?.renderer.type === "marigold"
              ? preparing
                ? "Preparing"
                : preparationLabel(preparation)
              : null
          }
          selected={templateName}
          onSelect={setTemplateName}
          jobs={preparationJobs}
        />

        <div className="app__workspace">
          {/* 2a: an uncalibrated template replaces the workspace with a single
              choice, so nothing else can be touched yet. Kind decides the
              whole shape of template.yaml (ADR-0014) -- every other control is
              meaningless or wrong until it is answered. */}
          {templateName && session.load !== "ready" ? (
            <p role={session.load === "error" ? "alert" : "status"}>
              {session.load === "error"
                ? "Could not load template configuration. Reload to try again."
                : "Loading template..."}
            </p>
          ) : templateName && !config ? (
            <KindPicker
              key={templateName}
              templateName={templateName}
              onAssigned={() => {
                session.reload();
                refreshTemplates(templateName);
              }}
            />
          ) : (
            <>
              {templateName && config?.renderer.type === "marigold" && (
                <MarigoldEditor
                  key={templateName}
                  templateName={templateName}
                  config={{ ...config, renderer: config.renderer }}
                  space={space}
                  colours={selected?.colours ?? []}
                  knownColours={knownColours}
                  design={design}
                  onDesignChange={setDesign}
                  onChange={setConfig}
                  preparation={preparation}
                  rendererControls={rendererControls}
                  calibrationRevision={session.calibrationRevision}
                  maskEdits={session.maskEdits}
                  onMaskEdits={session.setMaskEdits}
                  onPreviewPending={session.setPreviewPending}
                  savedConfig={session.saved}
                  onPrepare={() =>
                    void session.prepare(
                      preparation?.maps.reason === "photo_changed" ? "prepare_again" : "prepare",
                      preparation?.maps.reason === "photo_changed",
                    )
                  }
                />
              )}
              {templateName &&
                config?.renderer.type === "photo-warp" &&
                config?.kind === "colour-matrix" && (
                  <ColourMatrixEditor
                    key={templateName}
                    rendererControls={rendererControls}
                    templateName={templateName}
                    config={config}
                    space={space}
                    colours={selected?.colours ?? []}
                    onChange={setConfig}
                    design={design}
                    onDesignChange={setDesign}
                    onApprove={() => void session.approve()}
                  />
                )}
              {templateName &&
                config?.renderer.type === "photo-warp" &&
                config?.kind === "multiple" && (
                  <MultipleEditor
                    key={templateName}
                    rendererControls={rendererControls}
                    templateName={templateName}
                    config={config}
                    space={space}
                    onChange={setConfig}
                    design={design}
                    onDesignChange={setDesign}
                    knownColours={knownColours}
                  />
                )}
              {templateName &&
                config?.renderer.type === "photo-warp" &&
                config?.kind === "single" && (
                  <SingleEditor
                    key={templateName}
                    rendererControls={rendererControls}
                    templateName={templateName}
                    config={config}
                    space={space}
                    onChange={setConfig}
                    design={design}
                    onDesignChange={setDesign}
                  />
                )}
              {/* Templates are folders in the workspace, not something this
                  page creates: the calibrator calibrates. */}
              {!templateName &&
                (catalogState === "loading" ? (
                  <p role="status">Loading templates...</p>
                ) : catalogState === "error" ? (
                  <p role="alert">Could not load templates. Reload to try again.</p>
                ) : (
                  <p>No templates yet -- add a folder of photos under mockup-templates/.</p>
                ))}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { afterEach, expect, it, vi } from "vitest";
import type { Middleware } from "openapi-fetch";
import { api } from "./client";
import { getTemplateConfig } from "./calibrator";
import { getMaskHistory, getPreparation } from "./preparation";
import { READY, SINGLE } from "../test/marigold";

// Node requires absolute Request URLs; browsers resolve the app's relative paths.
vi.hoisted(() => {
  class BrowserRequest extends Request {
    constructor(input: RequestInfo | URL, init?: RequestInit) {
      super(typeof input === "string" ? new URL(input, "http://localhost") : input, init);
    }
  }
  vi.stubGlobal("Request", BrowserRequest);
});
const requests: Request[] = [];
const transport: Middleware = {
  onRequest({ request }) {
    requests.push(request);
    const body = request.url.endsWith("/config")
      ? SINGLE
      : request.url.endsWith("/preparation")
        ? READY
        : { checksum: "mask", undo_count: 0, strokes: [] };
    return Response.json(body, {
      headers: {
        ETag: '"current"',
        "Last-Modified": "Wed, 17 Sep 2026 18:30:00 GMT",
      },
    });
  },
};
afterEach(() => {
  api.eject(transport);
  requests.length = 0;
  vi.unstubAllGlobals();
});

it("bypasses previously cached calibration documents and mutable preparation state", async () => {
  api.use(transport);
  const name = "tee";
  // openapi-fetch's generated paths are relative in production. Its transport
  // hook receives the Request before it reaches the browser's HTTP cache.
  await getTemplateConfig(name);
  await getPreparation(name);
  await getMaskHistory(name, null);
  await getMaskHistory(name, "front");
  expect(requests).toHaveLength(4);
  expect(requests.every((request) => request.cache === "no-store")).toBe(true);
});

import type { components } from "./schema";
import { api } from "./client";
import { openEventStream, type EventStreamOptions } from "./sse";
export type Preparation = components["schemas"]["PreparationResponse"];
export type PreparationJob = components["schemas"]["PreparationJobResponse"];
export type MaskEdit = components["schemas"]["MaskEdit"];
export type MaskOperation = MaskEdit["operations"][number];
export type Runtime = components["schemas"]["MarigoldRuntimeResponse"];
export async function getPreparation(name: string, signal?: AbortSignal): Promise<Preparation> {
  const { data, error } = await api.GET("/api/templates/{name}/preparation", {
    cache: "no-store",
    params: { path: { name } },
    ...(signal ? { signal } : {}),
  });
  if (error || !data) throw new Error("Could not read template map status. Try again.");
  return data;
}
export async function getRuntime(): Promise<Runtime> {
  const { data, error } = await api.GET("/api/marigold/runtime");
  if (error || !data) throw new Error("Could not check the Marigold runtime.");
  return data;
}
export async function listPreparationJobs(): Promise<PreparationJob[]> {
  const { data, error } = await api.GET("/api/preparation/jobs");
  if (error || !data) throw new Error("Could not read the preparation queue.");
  return data;
}
export async function prepareTemplate(
  body: components["schemas"]["CreatePreparationRequest"],
): Promise<PreparationJob> {
  const { data, error } = await api.POST("/api/preparation/jobs", { body });
  if (error || !data) {
    const detail: unknown = error?.detail;
    const message =
      typeof detail === "string"
        ? detail
        : detail &&
            typeof detail === "object" &&
            "message" in detail &&
            typeof detail.message === "string"
          ? detail.message
          : "Preparation could not start. Try again.";
    throw new Error(message);
  }
  return data;
}
export async function cancelPreparation(identity: string): Promise<PreparationJob> {
  const { data, error } = await api.DELETE("/api/preparation/jobs/{identity}", {
    params: { path: { identity } },
  });
  if (error || !data) throw new Error("Could not cancel preparation. Try again.");
  return data;
}
export type PreparationEvent =
  | components["schemas"]["Event"]
  | PreparationJob
  | components["schemas"]["PreparationResyncResponse"];
export function followPreparation(id: string, options: EventStreamOptions<PreparationEvent>) {
  return openEventStream(`/api/preparation/jobs/${encodeURIComponent(id)}/events`, options);
}
export function maskUrl(
  name: string,
  placementId: string | null,
  automatic = false,
  revision = "",
) {
  const placement = placementId === null ? "" : `/placements/${encodeURIComponent(placementId)}`;
  return `/api/templates/${encodeURIComponent(name)}${placement}/mask?source=${automatic ? "automatic" : "edited"}&revision=${encodeURIComponent(revision)}`;
}
export type MaskHistory = components["schemas"]["MaskHistoryResponse"];
export async function getMaskHistory(
  name: string,
  placementId: string | null,
): Promise<MaskHistory> {
  const result =
    placementId === null
      ? await api.GET("/api/templates/{name}/mask-history", {
          cache: "no-store",
          params: { path: { name } },
        })
      : await api.GET("/api/templates/{name}/placements/{placement_id}/mask-history", {
          cache: "no-store",
          params: { path: { name, placement_id: placementId } },
        });
  if (result.error || !result.data)
    throw new Error("Could not read brush history. Saved masks remain available.");
  // openapi-fetch widens nested coordinate tuples. The response contract validates pairs.
  return result.data as unknown as MaskHistory;
}

/**
 * A typed `text/event-stream` reader over `fetch`, shared by the two run
 * resources: plan/apply runs (`pages/deploy/runStream.ts`) and AI runs
 * (`api/aiRuns.ts`). Both servers write the same frame,
 * `id: <n>\nevent: <type>\ndata: <json>\n\n`, and both end the stream after
 * the run's last event.
 *
 * **Why a hand-rolled `fetch` reader and not the browser's `EventSource`.**
 * `EventSource`'s constructor takes a URL and nothing else -- there is no way
 * to set a request header on its first connection, only on the *automatic*
 * reconnect after a drop, which the UA does on its own using whatever `id` it
 * last saw. Reattaching needs the header on the *first* request this page
 * ever makes to a run it did not start (a reload, or *View progress*), and
 * the servers read exactly that header (`Last-Event-ID`). `EventSource`
 * cannot ask for it; a plain `fetch` with a header can.
 *
 * No reconnect-on-drop logic is implemented here -- a run belongs to the
 * server regardless of who is watching, so a dropped connection loses
 * nothing a page reload (which reattaches) does not already recover.
 */

export interface EventStreamOptions<Event> {
  /** The last event id already known -- `undefined` asks the server for
   * everything, which is what a caller that has seen nothing wants. */
  lastEventId?: number | undefined;
  onEvent: (event: Event) => void;
  /** The stream closed because the run reached its last event -- there is
   * nothing more to read. */
  onDone?: () => void;
  /** The request itself failed (network, or a non-200 status) -- distinct
   * from `onDone`, which means the run finished normally. */
  onError?: (error: unknown) => void;
}

export interface EventStreamHandle {
  /** Stops reading and aborts the underlying request. Safe to call more than
   * once, and safe to call after the stream has already finished on its
   * own. */
  close: () => void;
}

function parseFrame<Event>(block: string): Event | null {
  let data: string | null = null;
  for (const line of block.split("\n")) {
    if (line.startsWith("data: ")) data = line.slice("data: ".length);
  }
  if (data === null) return null;
  return JSON.parse(data) as Event;
}

export function openEventStream<Event>(
  url: string,
  options: EventStreamOptions<Event>,
): EventStreamHandle {
  const controller = new AbortController();
  const headers =
    options.lastEventId !== undefined ? { "Last-Event-ID": String(options.lastEventId) } : {};

  async function read(): Promise<void> {
    let response: Response;
    try {
      response = await fetch(url, { headers, signal: controller.signal });
    } catch (error) {
      if (!controller.signal.aborted) options.onError?.(error);
      return;
    }
    if (!response.ok || response.body === null) {
      if (!controller.signal.aborted)
        options.onError?.(new Error(`event stream: HTTP ${response.status}`));
      return;
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    try {
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const frames = buffer.split("\n\n");
        // The last element is either "" (the buffer ended exactly on a frame
        // boundary) or a partial frame still waiting on more bytes -- either
        // way it is not parsed yet, only kept for the next chunk.
        buffer = frames.pop() ?? "";
        for (const block of frames) {
          const event = parseFrame<Event>(block);
          if (event !== null) options.onEvent(event);
        }
      }
      options.onDone?.();
    } catch (error) {
      if (!controller.signal.aborted) options.onError?.(error);
    }
  }

  void read();

  return {
    close: () => controller.abort(),
  };
}

import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import * as calibrator from "../api/calibrator";
import type { ColourReportRow } from "../types";
import { KindPicker } from "./KindPicker";

const CLEAN: ColourReportRow[] = [
  { filename: "sand.png", colour: "sand", clean: true },
  { filename: "black.png", colour: "black", clean: true },
];

const MESSY: ColourReportRow[] = [
  ...CLEAN,
  { filename: "Heather Grey.png", colour: "heather-grey", clean: false },
];

afterEach(() => vi.restoreAllMocks());
beforeEach(() => {
  vi.spyOn(calibrator, "getColourReport").mockResolvedValue(CLEAN);
});

function renderPicker(over: Partial<Parameters<typeof KindPicker>[0]> = {}) {
  const onAssigned = vi.fn();
  render(<KindPicker templateName="boxy-tee" onAssigned={onAssigned} {...over} />);
  return { onAssigned };
}

const ONE_PHOTO: ColourReportRow[] = [{ filename: "photo.png", colour: "photo", clean: true }];

describe("the default kind follows the photo count", () => {
  it("defaults to colour matrix when there are several photos", async () => {
    renderPicker();
    await waitFor(() => expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeChecked());
  });

  it("defaults to single, and disables colour matrix, for one photo", async () => {
    /* "One photo per colour" over a single file is a matrix of one -- which is
     * what `single` already is. Worse, accepting it names the colour after the
     * filename, so `photo.png` became a garment colour called "photo". */
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(ONE_PHOTO);
    renderPicker();

    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());
    expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeDisabled();
    expect(screen.getByText("needs more than one photo")).toBeInTheDocument();
  });

  it("multiple stays available for one photo", async () => {
    // A chart is one photo with several garments in it -- exactly the
    // single-photo case, so this must not be disabled alongside colour matrix.
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(ONE_PHOTO);
    renderPicker();
    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());
    expect(screen.getByRole("radio", { name: /Multiple/ })).toBeEnabled();
  });

  it("assigns single for a one-photo template without anyone touching a radio", async () => {
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(ONE_PHOTO);
    const assignSpy = vi.spyOn(calibrator, "assignKind").mockResolvedValue({
      kind: "single",
      colour: null,
      bounding_box: [
        { x: 0, y: 0 },
        { x: 1, y: 0 },
        { x: 1, y: 1 },
        { x: 0, y: 1 },
      ],
      renderer: {
        type: "photo-warp",
        config: {
          displace: { enabled: false, strength: 0 },
          shade: { enabled: true, opacity: 0.6, blend: "soft-light" },
        },
      },
    });
    renderPicker();
    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());

    fireEvent.click(screen.getByRole("button", { name: /Start calibrating/ }));
    await waitFor(() => expect(assignSpy).toHaveBeenCalledWith("boxy-tee", "single"));
  });

  it("a colour-matrix pick made before the report lands falls back to single", async () => {
    /* The report is fetched, so the count arrives after the first paint. A
     * choice that is no longer available has to give way rather than be
     * submitted. */
    let resolveReport: (rows: ColourReportRow[]) => void = () => {};
    vi.spyOn(calibrator, "getColourReport").mockReturnValue(
      new Promise<ColourReportRow[]>((resolve) => {
        resolveReport = resolve;
      }),
    );
    renderPicker();

    fireEvent.click(screen.getByRole("radio", { name: /Colour Matrix/ }));
    expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeChecked();

    resolveReport(ONE_PHOTO);
    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());
  });
});

describe("KindPicker", () => {
  it("asks the question and offers the three kinds", async () => {
    renderPicker();
    expect(screen.getByText("What kind of template is this?")).toBeInTheDocument();
    expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeInTheDocument();
    expect(screen.getByRole("radio", { name: /Multiple/ })).toBeInTheDocument();
    expect(screen.getByRole("radio", { name: /Single/ })).toBeInTheDocument();
  });

  it("explains what each kind means, since the names alone do not", () => {
    renderPicker();
    expect(screen.getByText("one photo per colour")).toBeInTheDocument();
    expect(screen.getByText("many garments, one photo")).toBeInTheDocument();
    expect(screen.getByText("one photo, one garment")).toBeInTheDocument();
  });

  it("shows the colour each filename yields, for the colour-matrix choice", async () => {
    renderPicker();
    await screen.findByText("sand.png");
    expect(screen.getByText("black.png")).toBeInTheDocument();
  });

  it("warns about a filename that is not already the slug", async () => {
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(MESSY);
    renderPicker();
    await screen.findByText("Heather Grey.png");
    expect(screen.getByText(/1 filename is not a colour slug/)).toBeInTheDocument();
  });

  it("says nothing about filenames when they are all clean", async () => {
    renderPicker();
    await screen.findByText("sand.png");
    expect(screen.queryByText(/is not a colour slug/)).not.toBeInTheDocument();
  });

  it("hides the colour report once a scene kind is chosen", async () => {
    renderPicker();
    await screen.findByText("sand.png");
    fireEvent.click(screen.getByRole("radio", { name: /Single/ }));
    // A scene kind has one photo and no colours to read off filenames
    //, so the report is not just irrelevant -- it is misleading.
    expect(screen.queryByText("sand.png")).not.toBeInTheDocument();
  });

  it("assigns the chosen kind and reports it upward", async () => {
    const assignSpy = vi.spyOn(calibrator, "assignKind").mockResolvedValue({
      kind: "colour-matrix",
      bounding_box: [
        { x: 0, y: 0 },
        { x: 1, y: 0 },
        { x: 1, y: 1 },
        { x: 0, y: 1 },
      ],
      renderer: {
        type: "photo-warp",
        config: {
          displace: { enabled: false, strength: 0 },
          shade: { enabled: true, opacity: 0.6, blend: "soft-light" },
        },
      },
    });
    const { onAssigned } = renderPicker();

    fireEvent.click(screen.getByRole("button", { name: /Start calibrating/ }));
    await waitFor(() => expect(assignSpy).toHaveBeenCalledWith("boxy-tee", "colour-matrix"));
    await waitFor(() => expect(onAssigned).toHaveBeenCalled());
  });

  it("assigns whichever kind is actually selected", async () => {
    const assignSpy = vi.spyOn(calibrator, "assignKind").mockResolvedValue({
      kind: "multiple",
      colour_coverage: "exact",
      placements: [],
      renderer: {
        type: "photo-warp",
        config: {
          displace: { enabled: false, strength: 0 },
          shade: { enabled: true, opacity: 0.6, blend: "soft-light" },
        },
      },
    });
    renderPicker();
    fireEvent.click(screen.getByRole("radio", { name: /Multiple/ }));
    fireEvent.click(screen.getByRole("button", { name: /Start calibrating/ }));
    await waitFor(() => expect(assignSpy).toHaveBeenCalledWith("boxy-tee", "multiple"));
  });

  it("reports a refusal instead of leaving the button dead", async () => {
    vi.spyOn(calibrator, "assignKind").mockRejectedValue(new Error("409"));
    renderPicker();
    fireEvent.click(screen.getByRole("button", { name: /Start calibrating/ }));
    await screen.findByText("could not set the kind");
  });

  it("survives the colour report failing", async () => {
    vi.spyOn(calibrator, "getColourReport").mockRejectedValue(new Error("network"));
    renderPicker();
    await waitFor(() =>
      expect(screen.getByRole("button", { name: /Start calibrating/ })).toBeEnabled(),
    );
  });
});

import { maskDraft } from "./maskDraft";
import { useEffect, useEffectEvent, useId, useRef, useState } from "react";
import type { MaskOperation } from "../api/preparation";
import type { BoundingBox } from "../types";
import { artworkTransform } from "./artworkTransform";

export type Stroke = Extract<MaskOperation, { type: "stroke" }>;
/** Mask pixels and strokes use original photo coordinates. The separate SVG
 * input layer captures a complete gesture so moving a placement cannot move
 * a saved exclusion and Undo never removes only part of a stroke. */
export function PlacementOverlay({
  box,
  designUrl,
  maskUrl,
  automaticMaskUrl,
  undoBases,
  operations,
  space,
  editing,
  mode,
  diameter,
  onStroke,
  showArtwork = true,
}: {
  showArtwork?: boolean;
  box: BoundingBox;
  designUrl: string;
  maskUrl: string | null;
  automaticMaskUrl: string | null;
  undoBases: string[];
  operations: MaskOperation[];
  space: [number, number];
  editing: boolean;
  mode: "mask" | "unmask";
  diameter: number;
  onStroke: (stroke: Stroke) => void;
}) {
  const id = useId().replaceAll(":", "");
  const [stroke, setStroke] = useState<Stroke | null>(null);
  const current = useRef<Stroke | null>(null);
  const cursor = useRef<SVGGElement>(null);
  function hideCursor() {
    cursor.current?.setAttribute("visibility", "hidden");
  }
  const { automatic, strokes, undoSaved } = maskDraft(operations);
  const base = automatic
    ? automaticMaskUrl
    : undoSaved
      ? undoBases[undoBases.length - undoSaved]
        ? `data:image/png;base64,${undoBases[undoBases.length - undoSaved]}`
        : maskUrl
      : maskUrl;
  function point(event: React.PointerEvent<SVGRectElement>): [number, number] | null {
    const svg = event.currentTarget.ownerSVGElement;
    const ctm = svg?.getScreenCTM();
    if (!svg || !ctm) return null;
    const p = svg.createSVGPoint();
    p.x = event.clientX;
    p.y = event.clientY;
    const result = p.matrixTransform(ctm.inverse());
    if (result.x >= 0 && result.x < space[0] && result.y >= 0 && result.y < space[1]) {
      cursor.current?.setAttribute("transform", `translate(${result.x} ${result.y})`);
      cursor.current?.setAttribute("visibility", "visible");
    } else hideCursor();
    return [
      Math.max(0, Math.min(space[0] - 1, result.x)),
      Math.max(0, Math.min(space[1] - 1, result.y)),
    ];
  }
  function finish() {
    const next = current.current;
    current.current = null;
    setStroke(null);
    if (next) onStroke(next);
  }
  // Leaving mask mode commits an active gesture once, including Escape while
  // the pointer is still held. The effect event uses the latest draft callback.
  const finishGesture = useEffectEvent(finish);
  useEffect(() => {
    if (editing) return () => finishGesture();
  }, [editing]);
  const all = stroke ? [...strokes, stroke] : strokes;
  const paths = all.map((s, i) => (
    <path
      key={i}
      d={
        s.points.map((p, j) => `${j ? "L" : "M"}${p[0]},${p[1]}`).join(" ") +
        (s.points.length === 1 ? ` l0.001,0` : "")
      }
      stroke={s.mode === "mask" ? "black" : "white"}
      strokeWidth={s.diameter_px}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
    />
  ));
  return (
    <g>
      <defs>
        <mask
          id={`cloth-${id}`}
          maskUnits="userSpaceOnUse"
          x={0}
          y={0}
          width={space[0]}
          height={space[1]}
        >
          <rect width={space[0]} height={space[1]} fill="white" />
          {base && <image href={base} width={space[0]} height={space[1]} />} {paths}
        </mask>
        <filter id={`invert-${id}`}>
          <feComponentTransfer>
            <feFuncR type="table" tableValues="1 0" />
            <feFuncG type="table" tableValues="1 0" />
            <feFuncB type="table" tableValues="1 0" />
          </feComponentTransfer>
        </filter>
        <mask
          id={`hidden-${id}`}
          maskUnits="userSpaceOnUse"
          x={0}
          y={0}
          width={space[0]}
          height={space[1]}
        >
          <g filter={`url(#invert-${id})`}>
            <rect width={space[0]} height={space[1]} fill="white" />
            {base && <image href={base} width={space[0]} height={space[1]} />} {paths}
          </g>
        </mask>
      </defs>
      {showArtwork && (
        <g mask={`url(#cloth-${id})`} pointerEvents="none">
          <foreignObject
            x={0}
            y={0}
            width={space[0]}
            height={space[1]}
            style={{ overflow: "visible" }}
          >
            <img
              src={designUrl}
              alt=""
              style={{
                width: 1,
                height: 1,
                position: "absolute",
                transformOrigin: "0 0",
                transform: artworkTransform(box),
                pointerEvents: "none",
              }}
            />
          </foreignObject>
        </g>
      )}
      {editing && (
        <>
          <rect
            width={space[0]}
            height={space[1]}
            fill="#e43737"
            opacity={0.32}
            mask={`url(#hidden-${id})`}
            pointerEvents="none"
          />
          <rect
            aria-label="Mask drawing area"
            width={space[0]}
            height={space[1]}
            fill="transparent"
            style={{ touchAction: "none", cursor: "none" }}
            onPointerEnter={point}
            onPointerLeave={hideCursor}
            onPointerDown={(event) => {
              if (event.button !== 0) return;
              event.stopPropagation();
              const p = point(event);
              if (!p) return;
              event.currentTarget.setPointerCapture(event.pointerId);
              const next: Stroke = { type: "stroke", mode, diameter_px: diameter, points: [p] };
              current.current = next;
              setStroke(next);
            }}
            onPointerMove={(event) => {
              const p = point(event);
              if (!current.current) return;
              event.stopPropagation();
              if (p) {
                const next = { ...current.current, points: [...current.current.points, p] };
                current.current = next;
                setStroke(next);
              }
            }}
            onPointerUp={(event) => {
              event.stopPropagation();
              finish();
            }}
            onPointerCancel={() => {
              finish();
              hideCursor();
            }}
            onLostPointerCapture={finish}
          />
          <g
            ref={cursor}
            aria-label="Brush footprint"
            visibility="hidden"
            pointerEvents="none"
            fill="none"
          >
            {/* SVG photo units match the stroke, including resize and DPR.
                  Non-scaling outlines stay legible on light and dark photos. */}
            <circle
              cx={0}
              cy={0}
              r={(stroke?.diameter_px ?? diameter) / 2}
              stroke="black"
              strokeWidth={3}
              vectorEffect="non-scaling-stroke"
            />
            <circle
              cx={0}
              cy={0}
              r={(stroke?.diameter_px ?? diameter) / 2}
              stroke="white"
              strokeWidth={1}
              vectorEffect="non-scaling-stroke"
            />
          </g>
        </>
      )}
    </g>
  );
}

import { useEffect, useState } from "react";
import { CheckCircleIcon } from "@phosphor-icons/react/dist/csr/CheckCircle";
import { ClockIcon } from "@phosphor-icons/react/dist/csr/Clock";
import type { PreparationJob } from "../api/preparation";
const stepLabels: Record<string, string> = {
  loading_models: "Loading models",
  normals: "Estimating surface direction",
  lighting: "Estimating garment lighting",
  depth: "Estimating depth",
  cpu_queued: "Waiting to build maps",
  building_maps: "Building maps",
  publication: "Publishing maps",
};
export function PreparationProgress({ job }: { job: PreparationJob }) {
  const [ticks, setTicks] = useState(0);
  const [base, setBase] = useState({ elapsed: job.elapsed, ticks });
  if (base.elapsed !== job.elapsed) setBase({ elapsed: job.elapsed, ticks });
  useEffect(() => {
    if (job.phase !== "running" && job.phase !== "cancelling") return;
    const timer = setInterval(() => setTicks((n) => n + 1), 1000);
    return () => clearInterval(timer);
  }, [job.phase]);
  const step = job.step.toLowerCase();
  const active = step.includes("normal")
    ? 0
    : step.includes("lighting")
      ? 1
      : step.includes("depth")
        ? 2
        : step.includes("build") || step.includes("bake")
          ? 3
          : -1;
  return (
    <>
      <p className="mg-row">
        <strong>
          {job.phase === "queued"
            ? `Waiting in queue${job.queue_position ? ` · ${job.queue_position}` : ""}`
            : (stepLabels[job.step] ?? job.step.replaceAll("_", " "))}
        </strong>
        <span>{Math.floor(job.elapsed + ticks - base.ticks)}s</span>
      </p>
      <p className="mg-help">
        {job.placements_completed} / {job.placements_total} placements
      </p>
      <ol className="mg-steps">
        {["Surface direction", "Garment lighting", "Depth", "Build maps"].map((label, i) => (
          <li
            key={label}
            className={i === active ? "mg-step--active" : i < active ? "mg-step--done" : ""}
          >
            {i < active ? <CheckCircleIcon /> : <ClockIcon />}
            {label}
          </li>
        ))}
      </ol>
    </>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { renderPreview } from "../api/calibrator";
import { Lightbox } from "./Lightbox";

/**
 * The Preview tab, for every template kind.
 *
 * The split it completes: the Calibrate tab renders *small* so that dragging
 * is instant, and this one renders at the photo's real size so there is
 * somewhere to actually judge the result. Both go through the same server-side
 * pipeline `apply` uses -- what changes between them is only how many pixels
 * the server is asked to spend.
 *
 * **Opening the tab renders; changing a box does not.** A full-size render of
 * a twelve-colour set is a lot of work, and it used to be kicked off by any
 * change to the config at all -- so nudging a box by a pixel re-rendered the
 * lot. Worse, the tiles could quietly become a picture of an older box than
 * the one on screen, which is the one thing a view you approve from must never
 * do. So the first look renders, and after that a changed config turns
 * Re-render red rather than silently re-running.
 *
 * The panel stays mounted while the Calibrate tab is in front, hidden rather
 * than unmounted. Otherwise every flick between tabs would throw the renders
 * away and start the set again -- and "there is none, so render" would fire on
 * a set that had just been rendered.
 *
 * Renders **sequentially**. Firing every colour at once does not make the set
 * arrive sooner -- the server runs the real pipeline for each -- it only makes
 * the *first* one arrive later, and buries the progress count.
 */

type PreviewBody = Parameters<typeof renderPreview>[1];

export interface PreviewJob {
  /** Stable across renders; also the lightbox's key. A colour name for a
   * colour matrix, the template name for the kinds with one output. */
  id: string;
  label: string;
  body: PreviewBody;
}

interface Props {
  fullQuality?: boolean;
  reference?: string;
  blocked?: string | null;
  prepareLabel?: string;
  onPrepare?: () => void;
  identity?: string;
  templateName: string;
  jobs: PreviewJob[];
  design: string;
  /** Whether this tab is the one in front. Mounted either way -- see the note
   * about tab flicks above -- so this both hides the panel and is what a first
   * look keys off. */
  active: boolean;
  /** Colour-matrix's "Approve & mark calibrated", which is a save. Omitted by
   * the kinds whose only save is the header's -- there is nothing extra to
   * approve when the tab shows one image. */
  onApprove?: () => void;
}

/** What one press of Render asked for. Set once and never mutated, so the
 * render loop's dependency on it is honest: a later edit produces a *new*
 * request, it does not redirect the one in flight. */
interface Request {
  key: string;
  templateName: string;
  design: string;
  jobs: PreviewJob[];
}

/** What has come back for a request. Stamped with the request's key so a
 * count from this run can never appear beside tiles from the last one. */
interface Result {
  key: string;
  rendered: Record<string, string>;
  done: number;
  failed: number;
}

function requestKey(templateName: string, design: string, jobs: PreviewJob[]): string {
  return `${templateName}|${design}|${JSON.stringify(jobs)}`;
}

export function PreviewPanel({
  fullQuality,
  reference,
  templateName,
  jobs,
  design,
  active,
  onApprove,
  blocked = null,
  prepareLabel = "Prepare template",
  onPrepare,
  identity = "",
}: Props) {
  const key = requestKey(templateName, design, jobs) + identity;
  const [request, setRequest] = useState<Request | null>(null);
  const [result, setResult] = useState<Result | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  const [actualSize, setActualSize] = useState(false);
  const urlsRef = useRef<string[]>([]);

  // Every blob this panel has made. Revoked wholesale when a run is replaced
  // or the tab goes away -- never per tile, which would pull an image out from
  // under one still on screen.
  const revokeAll = useCallback(() => {
    for (const url of urlsRef.current) URL.revokeObjectURL(url);
    urlsRef.current = [];
  }, []);
  useEffect(() => revokeAll, [revokeAll]);

  const start = useCallback(() => {
    revokeAll();
    setOpen(null);
    setResult({ key, rendered: {}, done: 0, failed: 0 });
    setRequest({ key, templateName, design, jobs });
  }, [key, templateName, design, jobs, revokeAll]);

  // The first look renders itself. Only ever the *first*: once a request
  // exists this is inert, so returning to the tab shows what was rendered
  // rather than spending the set again.
  //
  // Adjusted during render rather than from an effect. React re-renders
  // immediately and throws the intermediate output away, so the panel never
  // paints a "nothing yet" state it is about to replace -- where an effect
  // would both paint it and cost the cascading render that
  // `react-hooks/set-state-in-effect` exists to prevent. Nothing to revoke
  // here either: `request` only ever goes from null to set, so there cannot
  // be an earlier run's blobs to clean up. That is why this is not `start()`.
  if (active && request === null && !blocked) {
    setRequest({ key, templateName, design, jobs });
    setResult({ key, rendered: {}, done: 0, failed: 0 });
  }

  useEffect(() => {
    if (request === null || request.key !== key || blocked) return;
    let cancelled = false;

    void (async () => {
      for (const job of request.jobs) {
        if (cancelled) return;
        try {
          const url = await renderPreview(request.templateName, job.body, request.design, "full");
          if (cancelled) {
            URL.revokeObjectURL(url);
            return;
          }
          urlsRef.current.push(url);
          setResult((current) =>
            current === null || current.key !== request.key
              ? current
              : {
                  ...current,
                  rendered: { ...current.rendered, [job.id]: url },
                  done: current.done + 1,
                },
          );
        } catch {
          // One unreadable photo costs you that tile, not the whole tab.
          if (cancelled) return;
          setResult((current) =>
            current === null || current.key !== request.key
              ? current
              : { ...current, failed: current.failed + 1 },
          );
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [request, key, blocked]);

  const rendered = result?.key === request?.key ? (result?.rendered ?? {}) : {};
  const done = result?.done ?? 0;
  const failed = result?.failed ?? 0;
  // A run for an older config. Its images are still the last full-size renders
  // there are, and worth looking at -- they are just no longer of what the
  // editor is holding, and saying so is this banner's whole job.
  const stale = request !== null && request.key !== key;
  const complete = request !== null && done + failed >= request.jobs.length;
  // Everything asked for has come back, and it is a picture of what the editor
  // currently holds -- the only state in which approving means anything.
  const approvable = complete && !stale && failed === 0;

  const items = (request?.jobs ?? [])
    .map((job) => ({ id: job.id, label: job.label, url: rendered[job.id] }))
    .filter((item): item is { id: string; label: string; url: string } => Boolean(item.url));
  const openIndex = open === null ? -1 : items.findIndex((item) => item.id === open);

  return (
    <section
      className={jobs.length === 1 ? "preview-grid preview-grid--single" : "preview-grid"}
      hidden={!active}
    >
      {blocked && (
        <div className="mg-empty-preview">
          <p role="status">{blocked}</p>
          {onPrepare && (
            <button type="button" className="btn btn-primary" onClick={onPrepare}>
              {prepareLabel}
            </button>
          )}
        </div>
      )}
      <div className="preview-grid__head">
        {request === null ? (
          <span className="preview-grid__status">
            {jobs.length === 1 ? "not rendered yet" : `${jobs.length} colours, not rendered yet`}
          </span>
        ) : (
          <span className="preview-grid__count">{`${done} / ${request.jobs.length}`}</span>
        )}
        {request !== null && !complete && !stale && !blocked && (
          <span className="preview-grid__status">rendering at full size…</span>
        )}
        {fullQuality && complete && <span className="preview-grid__status">Full quality</span>}
        {failed > 0 && (
          <span className="preview-grid__failed">
            {`${failed} ${failed === 1 ? "preview" : "previews"} failed to render`}
          </span>
        )}
        {/* Which button is the loud one follows what there is to do. A config
            that has moved on since the render makes Re-render *red*: that is
            the one state where what you are looking at is not what you would
            be approving, and it is worth more than a line of prose beside the
            progress count, which is what it replaced. `.btn` alone is
            transparent in this design system, so the quiet one is explicitly
            `btn-secondary` rather than bare. */}
        <div className="preview-grid__actions">
          <button
            type="button"
            className={
              stale ? "btn btn-danger" : approvable ? "btn btn-secondary" : "btn btn-primary"
            }
            disabled={!!blocked}
            onClick={start}
          >
            {request === null ? "Render preview" : "Re-render"}
          </button>
          {onApprove && (
            <button
              type="button"
              className={approvable ? "btn btn-primary" : "btn btn-secondary"}
              onClick={onApprove}
            >
              Approve &amp; mark calibrated
            </button>
          )}
        </div>
      </div>

      {request === null ? (
        <p className="preview-grid__empty">
          Full-size renders, through the same pipeline <code>apply</code> uses — a few seconds each,
          which is why they are asked for rather than assumed. Click one to see it large.
        </p>
      ) : (
        <div className="preview-grid__tiles">
          {request.jobs.map((job) => {
            const url = rendered[job.id];
            return (
              <figure key={job.id} className="gallery__item preview-grid__tile">
                {url ? (
                  <button
                    type="button"
                    className="preview-grid__open"
                    onClick={() => setOpen(job.id)}
                    title="Open at full size"
                  >
                    <img src={url} alt={job.label} />
                  </button>
                ) : (
                  <div className="gallery__placeholder" />
                )}
                <figcaption>{job.label}</figcaption>
              </figure>
            );
          })}
        </div>
      )}

      {fullQuality && request !== null && (
        <>
          <p className="mg-help">Full-size renders. Click an image to see it large.</p>
          {reference && <p className="mg-help">{reference}</p>}
        </>
      )}

      {openIndex >= 0 && (
        <Lightbox
          items={items}
          index={openIndex}
          actualSize={actualSize}
          onActualSizeChange={setActualSize}
          onIndexChange={(next) => setOpen(items[next]?.id ?? null)}
          onClose={() => setOpen(null)}
        />
      )}
    </section>
  );
}

import { fireEvent, render, screen } from "@testing-library/react";
import { useState } from "react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { must } from "../test/helpers";
import type { BoundingBox } from "../types";
import { QuadEditor } from "./QuadEditor";

/** The template photo's true pixel size. `loadImage()` stubs the *displayed*
 * image at the same size, so every geometric expectation below reads the same
 * as it did when the overlay measured the image instead of being told. */
const SPACE: [number, number] = [400, 200];

const BOX_A: BoundingBox = [
  { x: 0, y: 0 },
  { x: 100, y: 0 },
  { x: 100, y: 100 },
  { x: 0, y: 100 },
];
const BOX_B: BoundingBox = [
  { x: 200, y: 0 },
  { x: 300, y: 0 },
  { x: 300, y: 100 },
  { x: 200, y: 100 },
];

function loadImage() {
  const img = screen.getByAltText("Rendered preview");
  Object.defineProperty(img, "naturalWidth", { value: 400, configurable: true });
  Object.defineProperty(img, "naturalHeight", { value: 200, configurable: true });
  fireEvent.load(img);
}

describe("QuadEditor", () => {
  it("renders no overlay until the image has loaded", () => {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={vi.fn()}
      />,
    );
    expect(container.querySelector(".quad-editor__overlay")).toBeNull();
  });

  it("puts the overlay in the template's space, not the displayed image's", () => {
    // The editor's canvas is a *downscaled* render, so the two differ. If the
    // overlay ever measured the image again, every box dragged on a real
    // template would be saved several times too small -- and nothing on
    // screen would look wrong while it happened.
    const { container } = render(
      <QuadEditor
        imageUrl="preview.webp"
        space={[4000, 5000]}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={vi.fn()}
      />,
    );
    loadImage(); // reports a 400x200 image
    expect(must(container.querySelector(".quad-editor__overlay")).getAttribute("viewBox")).toBe(
      "0 0 4000 5000",
    );
  });

  it("renders one box group per box, once loaded", () => {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A, BOX_B]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={vi.fn()}
      />,
    );
    loadImage();
    expect(container.querySelectorAll(".quad-editor__box")).toHaveLength(2);
  });

  it("clicking a non-selected box calls onSelect with its index", () => {
    const onSelect = vi.fn();
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A, BOX_B]}
        selectedIndex={0}
        onSelect={onSelect}
        onChangeBox={vi.fn()}
      />,
    );
    loadImage();
    const groups = container.querySelectorAll(".quad-editor__box");
    fireEvent.click(must(groups[1]));
    expect(onSelect).toHaveBeenCalledWith(1);
  });

  it("only the selected box shows drag handles", () => {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A, BOX_B]}
        selectedIndex={1}
        onSelect={vi.fn()}
        onChangeBox={vi.fn()}
      />,
    );
    loadImage();
    // 4 handles total, all belonging to the selected (second) box.
    expect(container.querySelectorAll(".quad-editor__handle")).toHaveLength(4);
    const groups = container.querySelectorAll(".quad-editor__box");
    expect(must(groups[0]).querySelectorAll(".quad-editor__handle")).toHaveLength(0);
    expect(must(groups[1]).querySelectorAll(".quad-editor__handle")).toHaveLength(4);
  });

  it("arrow key nudges the selected box by one pixel", () => {
    const onChangeBox = vi.fn();
    render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={onChangeBox}
      />,
    );
    loadImage();
    fireEvent.keyDown(screen.getByAltText("Rendered preview").parentElement as HTMLElement, {
      key: "ArrowRight",
    });
    expect(onChangeBox).toHaveBeenCalledWith(0, [
      { x: 1, y: 0 },
      { x: 101, y: 0 },
      { x: 101, y: 100 },
      { x: 1, y: 100 },
    ]);
  });

  it("shift+arrow nudges by the fast step", () => {
    const onChangeBox = vi.fn();
    render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={onChangeBox}
      />,
    );
    loadImage();
    fireEvent.keyDown(screen.getByAltText("Rendered preview").parentElement as HTMLElement, {
      key: "ArrowDown",
      shiftKey: true,
    });
    const [, box] = must(onChangeBox.mock.calls[0]);
    expect(must(box[0]).y).toBe(8);
  });

  describe("the box context menu", () => {
    const rect = (left: number, top: number, width: number, height: number): DOMRect =>
      ({
        left,
        top,
        width,
        height,
        right: left + width,
        bottom: top + height,
        x: left,
        y: top,
        toJSON: () => ({}),
      }) as DOMRect;

    const MENU_W = 150;
    const MENU_H = 90;

    /** jsdom reports every rect as zero-sized, so the three things the
     * positioning measures -- the canvas, the menu, and the clipping ancestor
     * -- have to be given sizes for the test to mean anything.
     *
     * Patched on the prototype rather than per node, because the menu is
     * measured inside a layout effect the moment it mounts: there is no point
     * at which a test could hold the node and still be ahead of it.
     *
     * The clip box is deliberately *shorter* than the canvas. That gap is
     * what the first attempt at this got wrong -- it measured against the
     * canvas, so the vertical overflow went unnoticed.
     */
    function sizeEverything({ clipW = 400, clipH = 200 } = {}) {
      vi.spyOn(Element.prototype, "getBoundingClientRect").mockImplementation(function (
        this: Element,
      ) {
        if (this.classList.contains("quad-editor__menu")) {
          const style = (this as HTMLElement).style;
          return rect(parseFloat(style.left || "0"), parseFloat(style.top || "0"), MENU_W, MENU_H);
        }
        if (this.tagName.toLowerCase() === "svg") return rect(0, 0, 400, 400);
        return rect(0, 0, clipW, clipH);
      });
    }

    function renderWithMenu() {
      render(
        <QuadEditor
          imageUrl="preview.png"
          space={SPACE}
          boxes={[BOX_A]}
          selectedIndex={0}
          onSelect={vi.fn()}
          onChangeBox={vi.fn()}
          onDuplicateSelected={vi.fn()}
          onBringSelectedToFront={vi.fn()}
          onDeleteSelected={vi.fn()}
        />,
      );
      loadImage();
      sizeEverything();
      return must(document.querySelector(".quad-editor__box"));
    }

    function openAt(box: Element, clientX: number, clientY: number) {
      fireEvent.contextMenu(box, { clientX, clientY });
      const menu = must(document.querySelector<HTMLElement>(".quad-editor__menu"));
      return {
        left: parseFloat(menu.style.left),
        top: parseFloat(menu.style.top),
        right: parseFloat(menu.style.left) + MENU_W,
        bottom: parseFloat(menu.style.top) + MENU_H,
        el: menu,
      };
    }

    it("opens with all three actions", () => {
      const { el } = openAt(renderWithMenu(), 20, 20);
      expect([...el.querySelectorAll('[role="menuitem"]')].map((b) => b.textContent)).toEqual([
        "Duplicate",
        "Bring to front",
        "Delete ⌫",
      ]);
    });

    it("opens at the click when there is room", () => {
      const menu = openAt(renderWithMenu(), 20, 20);
      expect([menu.left, menu.top]).toEqual([20, 20]);
    });

    it("stays inside the clip box when opened near the far corner", () => {
      /* The bug: `.app__preview` clips its overflow, so a menu opening
       * right-and-down from the rightmost box had two of its three items cut
       * off -- "Delete" was unreachable for the last garment in a chart. */
      const menu = openAt(renderWithMenu(), 380, 190);
      expect(menu.right).toBeLessThanOrEqual(400);
      expect(menu.bottom).toBeLessThanOrEqual(200);
    });

    it("is not offered when the editor has no box actions", () => {
      render(
        <QuadEditor
          imageUrl="preview.png"
          space={SPACE}
          boxes={[BOX_A]}
          selectedIndex={0}
          onSelect={vi.fn()}
          onChangeBox={vi.fn()}
        />,
      );
      loadImage();
      fireEvent.contextMenu(must(document.querySelector(".quad-editor__box")), {
        clientX: 20,
        clientY: 20,
      });
      expect(document.querySelector(".quad-editor__menu")).toBeNull();
    });
  });

  it("a non-arrow key is a no-op", () => {
    const onChangeBox = vi.fn();
    render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={onChangeBox}
      />,
    );
    loadImage();
    fireEvent.keyDown(screen.getByAltText("Rendered preview").parentElement as HTMLElement, {
      key: "a",
    });
    expect(onChangeBox).not.toHaveBeenCalled();
  });
});

/** jsdom implements no SVG geometry, so the two calls the editor maps screen
 * pixels through have to be supplied. Identity, so image space *is* client
 * space and the arithmetic in the assertions stays readable. */
function stubSvgGeometry(): () => void {
  const proto = SVGSVGElement.prototype as unknown as {
    createSVGPoint: () => DOMPoint;
    getScreenCTM: () => DOMMatrix | null;
  };
  const original = { point: proto.createSVGPoint, ctm: proto.getScreenCTM };
  proto.createSVGPoint = () => {
    const p = { x: 0, y: 0, matrixTransform: () => ({ x: p.x, y: p.y }) };
    return p as unknown as DOMPoint;
  };
  proto.getScreenCTM = () => ({ inverse: () => ({}) }) as unknown as DOMMatrix;
  return () => {
    proto.createSVGPoint = original.point;
    proto.getScreenCTM = original.ctm;
  };
}

describe("sliding a whole box", () => {
  let restore = () => {};
  beforeEach(() => {
    restore = stubSvgGeometry();
  });
  afterEach(() => restore());

  function renderDraggable(onChangeBox = vi.fn(), onSelect = vi.fn()) {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A, BOX_B]}
        selectedIndex={0}
        onSelect={onSelect}
        onChangeBox={onChangeBox}
      />,
    );
    loadImage();
    return container;
  }

  const overlay = (container: HTMLElement) =>
    must(container.querySelector(".quad-editor__overlay"));

  const press = (target: Element, clientX: number, clientY: number, button = 0) =>
    fireEvent.pointerDown(target, { button, clientX, clientY, pointerId: 1 });

  it("dragging inside a box translates all four corners by the same delta", () => {
    const onChangeBox = vi.fn();
    const container = renderDraggable(onChangeBox);
    press(must(container.querySelector(".quad-editor__polygon")), 10, 10);
    fireEvent.pointerMove(overlay(container), { clientX: 40, clientY: 25 });

    expect(onChangeBox).toHaveBeenCalledWith(0, [
      { x: 30, y: 15 },
      { x: 130, y: 15 },
      { x: 130, y: 115 },
      { x: 30, y: 115 },
    ]);
  });

  it("pressing a dimmed box selects it and drags that one", () => {
    const onChangeBox = vi.fn();
    const onSelect = vi.fn();
    const container = renderDraggable(onChangeBox, onSelect);
    press(must(container.querySelectorAll(".quad-editor__polygon")[1]), 0, 0);
    expect(onSelect).toHaveBeenCalledWith(1);

    fireEvent.pointerMove(overlay(container), { clientX: 5, clientY: 0 });
    const [index] = must(onChangeBox.mock.calls[0]);
    expect(index).toBe(1);
  });

  it("stops moving once the pointer is released", () => {
    const onChangeBox = vi.fn();
    const container = renderDraggable(onChangeBox);
    press(must(container.querySelector(".quad-editor__polygon")), 0, 0);
    fireEvent.pointerUp(overlay(container));
    fireEvent.pointerMove(overlay(container), { clientX: 90, clientY: 90 });
    expect(onChangeBox).not.toHaveBeenCalled();
  });

  it("slides from the box as it was when the gesture started, not compounding", () => {
    // A parent that applies each change, as the calibrator does, so the
    // second move sees the already-moved box in props. Measured from the live
    // box, the same pointer position would move it again.
    const onChangeBox = vi.fn();
    function Controlled() {
      const [box, setBox] = useState(BOX_A);
      return (
        <QuadEditor
          imageUrl="preview.png"
          space={SPACE}
          boxes={[box]}
          selectedIndex={0}
          onSelect={vi.fn()}
          onChangeBox={(index, next) => {
            onChangeBox(index, next);
            setBox(next);
          }}
        />
      );
    }
    const { container } = render(<Controlled />);
    loadImage();
    press(must(container.querySelector(".quad-editor__polygon")), 10, 10);
    fireEvent.pointerMove(overlay(container), { clientX: 40, clientY: 25 });
    fireEvent.pointerMove(overlay(container), { clientX: 40, clientY: 25 });
    fireEvent.pointerUp(overlay(container));

    const slid = [
      { x: 30, y: 15 },
      { x: 130, y: 15 },
      { x: 130, y: 115 },
      { x: 30, y: 115 },
    ];
    expect(onChangeBox.mock.calls).toEqual([
      [0, slid],
      [0, slid],
    ]);
  });

  it("ignores a right-press, which is the context-menu gesture", () => {
    const onChangeBox = vi.fn();
    const container = renderDraggable(onChangeBox);
    press(must(container.querySelector(".quad-editor__polygon")), 0, 0, 2);
    fireEvent.pointerMove(overlay(container), { clientX: 90, clientY: 90 });
    expect(onChangeBox).not.toHaveBeenCalled();
  });
});

describe("the on-canvas box captions", () => {
  function renderLabelled(props: Partial<Parameters<typeof QuadEditor>[0]> = {}) {
    const onLabelChange = vi.fn();
    const view = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A, BOX_B]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={vi.fn()}
        labels={["black", ""]}
        onLabelChange={onLabelChange}
        labelPlaceholder="assign colour…"
        labelSuggestions={["ivory"]}
        {...props}
      />,
    );
    loadImage();
    return { ...view, onLabelChange };
  }

  it("captions every box, and prompts on the ones with no colour", () => {
    renderLabelled();
    expect(screen.getByRole("button", { name: "black" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "assign colour…" })).toBeInTheDocument();
  });

  it("positions a caption under its box, in percentages of the image", () => {
    const { container } = renderLabelled();
    // BOX_A spans x 0-100 of a 400px-wide image, and reaches y 100 of 200.
    const caption = must(container.querySelector<HTMLElement>(".quad-editor__label"));
    expect(caption.style.left).toBe("12.5%");
    expect(caption.style.top).toBe("50%");
  });

  it("clicking a caption opens it for editing and reports what is typed", () => {
    const { onLabelChange } = renderLabelled();
    fireEvent.click(screen.getByRole("button", { name: "black" }));
    const field = screen.getByLabelText("Colour for box 1");
    expect(field).toHaveFocus();

    fireEvent.change(field, { target: { value: "moss" } });
    expect(onLabelChange).toHaveBeenCalledWith(0, "moss");
  });

  it("Enter closes the editor", () => {
    renderLabelled();
    fireEvent.click(screen.getByRole("button", { name: "black" }));
    fireEvent.keyDown(screen.getByLabelText("Colour for box 1"), { key: "Enter" });
    expect(screen.queryByLabelText("Colour for box 1")).not.toBeInTheDocument();
  });

  it("arrow keys typed into a caption do not nudge the box", () => {
    const onChangeBox = vi.fn();
    const onDeleteSelected = vi.fn();
    renderLabelled({ onChangeBox, onDeleteSelected });
    fireEvent.click(screen.getByRole("button", { name: "black" }));
    const field = screen.getByLabelText("Colour for box 1");
    fireEvent.keyDown(field, { key: "ArrowRight" });
    fireEvent.keyDown(field, { key: "Backspace" });
    expect(onChangeBox).not.toHaveBeenCalled();
    expect(onDeleteSelected).not.toHaveBeenCalled();
  });

  it("hiding the chrome hides the captions with the outlines", () => {
    const { container } = renderLabelled({ outlines: "none" });
    expect(container.querySelectorAll(".quad-editor__label")).toHaveLength(0);
  });

  it("with only the selected outline shown, only its caption is", () => {
    const { container } = renderLabelled({ outlines: "selected" });
    expect(container.querySelectorAll(".quad-editor__label")).toHaveLength(1);
    expect(screen.getByRole("button", { name: "black" })).toBeInTheDocument();
  });
});

describe("resizing a box from a corner", () => {
  let restore = () => {};
  beforeEach(() => {
    restore = stubSvgGeometry();
  });
  afterEach(() => restore());

  /** BOX_A is the unit square scaled to 100 -- corners at (0,0), (100,0),
   * (100,100), (0,100) -- so a factor of `f` about the opposite corner lands
   * on numbers you can read straight off the assertion. */
  function renderResizable(onChangeBox = vi.fn()) {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={onChangeBox}
      />,
    );
    loadImage();
    return container;
  }

  const overlay = (container: HTMLElement) =>
    must(container.querySelector(".quad-editor__overlay"));

  /** Grabs the bottom-right handle, whose opposite corner is the origin. */
  const grabBottomRight = (container: HTMLElement) =>
    fireEvent.pointerDown(must(container.querySelectorAll(".quad-editor__handle")[2]), {
      button: 0,
      clientX: 100,
      clientY: 100,
      pointerId: 1,
    });

  it("plain-drags one corner and leaves the other three alone", () => {
    const onChangeBox = vi.fn();
    const container = renderResizable(onChangeBox);
    grabBottomRight(container);
    fireEvent.pointerMove(overlay(container), { clientX: 160, clientY: 40 });

    expect(onChangeBox).toHaveBeenLastCalledWith(0, [
      { x: 0, y: 0 },
      { x: 100, y: 0 },
      { x: 160, y: 40 },
      { x: 0, y: 100 },
    ]);
  });

  it("shift-drag scales the whole box about the opposite corner", () => {
    const onChangeBox = vi.fn();
    const container = renderResizable(onChangeBox);
    grabBottomRight(container);
    // Straight out along the diagonal to (200, 200): twice as far from the
    // anchor at the origin, so every corner doubles.
    fireEvent.pointerMove(overlay(container), { clientX: 200, clientY: 200, shiftKey: true });

    expect(onChangeBox).toHaveBeenLastCalledWith(0, [
      { x: 0, y: 0 },
      { x: 200, y: 0 },
      { x: 200, y: 200 },
      { x: 0, y: 200 },
    ]);
  });

  it("alt-drag scales about the box's own centre", () => {
    const onChangeBox = vi.fn();
    const container = renderResizable(onChangeBox);
    grabBottomRight(container);
    // The centre is (50,50) and the grabbed corner is 50 away on each axis;
    // dragging to (150,150) doubles that distance, so the box doubles around
    // the centre and its top-left goes negative.
    fireEvent.pointerMove(overlay(container), { clientX: 150, clientY: 150, altKey: true });

    expect(onChangeBox).toHaveBeenLastCalledWith(0, [
      { x: -50, y: -50 },
      { x: 150, y: -50 },
      { x: 150, y: 150 },
      { x: -50, y: 150 },
    ]);
  });

  it("scales from the box as it was when the gesture started, not compounding", () => {
    const onChangeBox = vi.fn();
    // A parent that applies each change, as the calibrator does, so the
    // second move sees the already-doubled box in props.
    function Controlled() {
      const [box, setBox] = useState(BOX_A);
      return (
        <QuadEditor
          imageUrl="preview.png"
          space={SPACE}
          boxes={[box]}
          selectedIndex={0}
          onSelect={vi.fn()}
          onChangeBox={(index, next) => {
            onChangeBox(index, next);
            setBox(next);
          }}
        />
      );
    }
    const { container } = render(<Controlled />);
    loadImage();
    grabBottomRight(container);
    fireEvent.pointerMove(overlay(container), { clientX: 200, clientY: 200, shiftKey: true });
    fireEvent.pointerMove(overlay(container), { clientX: 200, clientY: 200, shiftKey: true });

    // Same pointer position twice means the same doubled box twice. A
    // projection about a fixed anchor happens to land in the same place from
    // the live box too, so the sliding case above is the one that catches a
    // gesture reading live props; this one pins the callback sequence.
    const doubled = [
      { x: 0, y: 0 },
      { x: 200, y: 0 },
      { x: 200, y: 200 },
      { x: 0, y: 200 },
    ];
    expect(onChangeBox.mock.calls).toEqual([
      [0, doubled],
      [0, doubled],
    ]);
  });
});

import { PreparationProgress } from "./PreparationProgress";
import { preparationLabel, marigoldMapsReady } from "./preparationLabel";
import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { getRuntime, type Preparation, type Runtime } from "../api/preparation";
import type { Renderer } from "../types";
export function RendererPanel({
  settings,
  renderer,
  onRendererChange,
  preparation,
  onPrepare,
  onCancel,
  pending,
  error,
}: {
  settings: (runtime: Runtime | null) => ReactNode;
  renderer: Renderer;
  onRendererChange: (renderer: Renderer["type"]) => void;
  preparation: Preparation | null;
  onPrepare: (action: "prepare" | "prepare_again" | "retry", resetMasksForPhoto?: boolean) => void;
  onCancel: () => void;
  pending: boolean;
  error: string;
}) {
  const [runtime, setRuntime] = useState<Runtime | null>(null);
  const [runtimeError, setRuntimeError] = useState("");
  useEffect(() => {
    if (renderer.type !== "marigold") return;
    let active = true;
    getRuntime()
      .then((value) => {
        if (active) setRuntime(value);
      })
      .catch((e) => {
        if (active) setRuntimeError(e instanceof Error ? e.message : "Could not check runtime");
      });
    return () => {
      active = false;
    };
  }, [renderer.type]);
  const job = preparation?.active_job;
  // A CPU rebuild reuses saved predictions and takes seconds, so it gets a
  // spinner where the stages go -- not the GPU run's steps, timer and Cancel.
  const rebuilding = job?.kind === "rebuild";
  const label = pending ? "Preparing" : preparationLabel(preparation);
  const recovery = preparation?.maps.reason === "photo_changed";
  const action =
    preparation?.latest_job?.phase === "failed"
      ? "retry"
      : recovery
        ? "prepare_again"
        : marigoldMapsReady(preparation?.maps)
          ? "prepare_again"
          : "prepare";
  return (
    <section className="realism mg-preparation">
      <h3 className="realism__heading">Renderer</h3>
      <select
        id="template-renderer"
        aria-label="Renderer"
        value={renderer.type}
        onChange={(e) => onRendererChange(e.target.value as Renderer["type"])}
      >
        <option value="photo-warp">Photo warp</option>
        <option value="marigold">Marigold</option>
      </select>
      {renderer.type === "marigold" && (
        <>
          <div className="mg-row">
            <strong>Template maps</strong>
            <span
              className={`tag mg-status${label === "Ready" ? " mg-status--ready" : label === "Failed" ? " mg-status--failed" : ""}`}
            >
              {label}
            </span>
          </div>
          {!job && preparation?.maps.state === "out_of_date" && preparation.maps.reason && (
            <p className="mg-help">{preparation.maps.message}</p>
          )}
          {rebuilding ? (
            <div className="mg-progress mg-rebuild" role="status">
              <span className="dv-spinner" aria-hidden="true" />
              Rebuilding maps
            </div>
          ) : job ? (
            <div className="mg-progress">
              <PreparationProgress job={job} />
              <button
                className="btn btn-secondary mg-wide"
                disabled={pending || job.phase === "cancelling"}
                onClick={onCancel}
              >
                {job.phase === "cancelling" ? "Cancelling…" : "Cancel preparation"}
              </button>
            </div>
          ) : (
            <button
              type="button"
              className={
                "btn mg-wide " +
                (action === "prepare_again" && !recovery ? "btn-secondary" : "btn-primary")
              }
              disabled={pending || !preparation || !runtime?.available}
              onClick={() => onPrepare(action, recovery && action !== "retry")}
            >
              {action === "retry"
                ? "Retry preparation"
                : recovery
                  ? "Reset masks and prepare"
                  : action === "prepare_again"
                    ? "Prepare again"
                    : "Prepare template"}
            </button>
          )}
          {(preparation?.latest_job?.error || error) && (
            <p role="alert" className="mg-error">
              {error || preparation?.latest_job?.error}
            </p>
          )}
          {(!runtime?.available || runtimeError) && (
            <p className="mg-help" role="status">
              {runtimeError || runtime?.problem || "Checking Marigold runtime…"}
            </p>
          )}
          {preparation &&
            marigoldMapsReady(preparation.maps) &&
            preparation.prepared_engine &&
            runtime?.engine_version &&
            preparation.prepared_engine !== runtime.engine_version && (
              <p className="mg-help">
                These maps were prepared with {preparation.prepared_engine}. They remain usable.
                Prepare again to use {runtime.engine_version}.
              </p>
            )}
          {job && !rebuilding ? (
            <p className="mg-help">You can close this browser. Preparation will continue.</p>
          ) : (
            !job && action === "retry" && <p className="mg-help">Completed steps will be reused.</p>
          )}
          {settings(runtime)}
        </>
      )}
    </section>
  );
}

import { marigoldMapsReady } from "./preparationLabel";
import type { PreparationJob } from "../api/preparation";
import { useMemo, useState } from "react";
import { templateThumbnailUrl } from "../api/calibrator";
import type { TemplateKind, TemplateSummary } from "../types";

/**
 * The template picker, as a rail rather than a dropdown (wireframe 2a).
 *
 * The point of the change is ordering: a dropdown presents 34 templates as an
 * undifferentiated list you have to already know your way around, while the
 * rail leads with the ones that are not finished and says what each is missing.
 * "Which do I open next?" stops being a question the user has to answer from
 * memory.
 *
 * Status is server-derived (`TemplateSummary.status`), so this component never
 * decides what "calibrated" means -- it only arranges what it is told.
 */

const KIND_LABELS: Record<TemplateKind, string> = {
  "colour-matrix": "Colour Matrix",
  multiple: "Multiple",
  single: "Single",
};

const VISIBLE_LIMIT = 5;
/** Rows shown per group before "+ N more". The rail is a sidebar, not the
 * page: a 34-template workspace should not push the calibrate button off
 * screen. */

type StatusFilter = "needs" | "all" | "done";

function needsCalibration(t: TemplateSummary): boolean {
  return t.renderer === "marigold"
    ? Boolean(t.maps && !marigoldMapsReady(t.maps))
    : t.status === "needs-calibration";
}

function countLabel(n: number, noun: string): string {
  return `${n} ${noun}${n === 1 ? "" : "s"}`;
}

/** What the row says under the name: what is missing, or what it holds. */
function describe(t: TemplateSummary): string {
  const kind = t.kind ? KIND_LABELS[t.kind] : null;
  if (t.renderer === "marigold") return kind ?? "Unknown";
  if (needsCalibration(t)) {
    const reason = t.status_reason ?? "not calibrated";
    return kind ? `${kind} · ${reason}` : reason;
  }
  return `${kind ?? "Unknown"} · ${countLabel(t.colours.length, "colour")}`;
}

/** The row's photo, or a blank tile when there isn't one.
 *
 * A template directory can exist before any photo is in it -- an interrupted
 * upload, or a folder made by hand -- and `/thumbnail` 404s for those. Without
 * this the browser draws its own broken-image icon, which reads as the rail
 * being broken rather than as the template being empty. */
function Thumb({ name }: { name: string }) {
  const [failed, setFailed] = useState(false);
  if (failed) return <span className="template-rail__thumb template-rail__thumb--empty" />;
  return (
    <img
      className="template-rail__thumb"
      src={templateThumbnailUrl(name)}
      alt=""
      loading="lazy"
      onError={() => setFailed(true)}
    />
  );
}

interface RowProps {
  preparationStatus?: string | null;
  template: TemplateSummary;
  selected: boolean;
  onSelect: (name: string) => void;
}

function Row({ template, selected, onSelect, preparationStatus }: RowProps) {
  const classes = ["template-rail__item"];
  if (selected) classes.push("template-rail__item--active");
  if (needsCalibration(template)) classes.push("template-rail__item--needs");
  return (
    <button
      type="button"
      className={classes.join(" ")}
      data-template={template.name}
      aria-current={selected ? "true" : undefined}
      onClick={() => onSelect(template.name)}
    >
      <Thumb name={template.name} />
      <span className="template-rail__text">
        <span className="template-rail__name">{template.name}</span>
        <span className="template-rail__meta">{describe(template)}</span>
        {template.renderer === "marigold" && (
          <span
            className={`mg-rail-state${marigoldMapsReady(template.maps) ? " mg-rail-state--ready" : ""}`}
          >
            {preparationStatus ||
              (template.maps
                ? marigoldMapsReady(template.maps)
                  ? "Ready"
                  : "Needs maps"
                : "Checking maps")}
          </span>
        )}
      </span>
    </button>
  );
}

interface GroupProps {
  jobs?: PreparationJob[];
  selectedPreparationStatus?: string | null;
  heading: string;
  templates: TemplateSummary[];
  selected: string | null;
  onSelect: (name: string) => void;
}

function Group({
  heading,
  templates,
  selected,
  onSelect,
  jobs = [],
  selectedPreparationStatus,
}: GroupProps) {
  const [expanded, setExpanded] = useState(false);
  if (templates.length === 0) return null;

  const hidden = expanded ? 0 : Math.max(0, templates.length - VISIBLE_LIMIT);
  const visible = expanded ? templates : templates.slice(0, VISIBLE_LIMIT);

  return (
    <section className="template-rail__group">
      <h2 className="template-rail__heading">{`${heading} · ${templates.length}`}</h2>
      {visible.map((t) => (
        <Row
          key={t.name}
          template={t}
          selected={t.name === selected}
          onSelect={onSelect}
          preparationStatus={
            t.name === selected
              ? (selectedPreparationStatus ?? null)
              : jobs.find((job) => job.template === t.name)?.phase === "queued"
                ? "Queued"
                : jobs.some((job) => job.template === t.name)
                  ? "Preparing"
                  : null
          }
        />
      ))}
      {hidden > 0 && (
        <button type="button" className="template-rail__more" onClick={() => setExpanded(true)}>
          {`+ ${hidden} more`}
        </button>
      )}
    </section>
  );
}

interface TemplateRailProps {
  selectedPreparationStatus?: string | null;
  jobs?: PreparationJob[];
  templates: TemplateSummary[];
  selected: string | null;
  onSelect: (name: string) => void;
}

export function TemplateRail({
  templates,
  selected,
  onSelect,
  jobs = [],
  selectedPreparationStatus,
}: TemplateRailProps) {
  const marigold = templates.some((t) => t.renderer === "marigold");
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<StatusFilter>("all");
  const [kind, setKind] = useState<TemplateKind | null>(null);

  const outstanding = useMemo(() => templates.filter(needsCalibration), [templates]);
  const isReady = (t: TemplateSummary) =>
    t.renderer === "marigold" ? marigoldMapsReady(t.maps) : !needsCalibration(t);
  const doneCount = templates.filter(isReady).length;
  // Held separately so the banner's callback has something TypeScript can
  // narrow -- `outstanding.length > 0` in JSX does not narrow `outstanding[0]`.
  const nextUp = outstanding.find((template) => template.renderer !== "marigold") ?? null;

  const shown = useMemo(() => {
    const term = search.trim().toLowerCase();
    return templates.filter((t) => {
      if (term && !t.name.toLowerCase().includes(term)) return false;
      if (status === "needs" && !needsCalibration(t)) return false;
      if (status === "done" && !isReady(t)) return false;
      if (kind && t.kind !== kind) return false;
      return true;
    });
  }, [templates, search, status, kind]);

  const pending = shown.filter(needsCalibration);
  const finished = shown.filter((t) => !needsCalibration(t));

  return (
    <nav className="template-rail" aria-label="Templates">
      {nextUp && (
        <div className="template-rail__banner">
          <p className="template-rail__banner-text">
            {`${countLabel(outstanding.length, "template")} need${
              outstanding.length === 1 ? "s" : ""
            } calibration`}
          </p>
          <button type="button" className="btn btn-primary" onClick={() => onSelect(nextUp.name)}>
            Calibrate next →
          </button>
        </div>
      )}

      <input
        className="input template-rail__search"
        type="search"
        aria-label="Search templates"
        placeholder="Search templates…"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      <div className="template-rail__filters">
        {(
          [
            ["all", `All ${templates.length}`],
            ["needs", `${marigold ? "Needs maps" : "Needs calibration"} ${outstanding.length}`],
            ["done", `${marigold ? "Ready" : "Done"} ${doneCount}`],
          ] as const
        ).map(([value, label]) => (
          <button
            key={value}
            type="button"
            className={`tag template-rail__pill${status === value ? " template-rail__pill--on" : ""}`}
            aria-pressed={status === value}
            onClick={() => setStatus(value)}
          >
            {label}
          </button>
        ))}
      </div>

      <div className="template-rail__filters">
        {(Object.keys(KIND_LABELS) as TemplateKind[]).map((value) => (
          <button
            key={value}
            type="button"
            className={`tag template-rail__pill${kind === value ? " template-rail__pill--on" : ""}`}
            aria-pressed={kind === value}
            onClick={() => setKind((current) => (current === value ? null : value))}
          >
            {KIND_LABELS[value]}
          </button>
        ))}
      </div>

      {shown.length === 0 ? (
        <p className="template-rail__empty">No templates match.</p>
      ) : marigold ? (
        <Group
          heading="Templates"
          templates={shown}
          selected={selected}
          onSelect={onSelect}
          jobs={jobs}
          selectedPreparationStatus={selectedPreparationStatus ?? null}
        />
      ) : (
        <>
          <Group
            heading="Needs calibration"
            templates={pending}
            selected={selected}
            onSelect={onSelect}
          />
          <Group
            heading="Calibrated"
            templates={finished}
            selected={selected}
            onSelect={onSelect}
          />
        </>
      )}
      {jobs.length > 0 && (
        <section className="mg-queue">
          <h2 className="template-rail__heading">Preparation queue</h2>
          {jobs.map((job) => (
            <button
              className="mg-queue-entry"
              type="button"
              key={job.id}
              onClick={() => onSelect(job.template)}
            >
              <span>{job.template}</span>
              <span>
                {job.phase === "queued"
                  ? "Queued"
                  : job.kind === "rebuild"
                    ? "Rebuilding maps"
                    : "Preparing"}
              </span>
            </button>
          ))}
        </section>
      )}
    </nav>
  );
}

